        const stagesDistinct = Array.from(new Set(marcasDaSaida.map(m => m.stage)));
        const hasWin = marcasDaSaida.some(m => ["loi","contract","construction","opening"].includes(m.stage));
        const isExpanded = expanded === s.id;
