  .agent-mini .name { font-weight:600; font-size:12px; line-height:1.2; margin-bottom:3px; }
  .agent-mini .desc { font-size:10.5px; color:var(--steel); line-height:1.4; }

  /* MODAL */
  .modal-bg { display:none; position:fixed; inset:0; background:rgba(13,17,23,0.7); z-index:200; justify-content:center; align-items:center; backdrop-filter:blur(4px); padding:20px; }
  .modal-bg.active { display:flex; }
  .modal { background:var(--paper); border-radius:12px; padding:28px; width:100%; max-width:680px; box-shadow:0 20px 60px rgba(0,0,0,0.4); max-height:90vh; overflow-y:auto; }
  .modal.wide { max-width:920px; }
  .modal h2 { font-family:var(--display); font-size:24px; font-weight:700; margin-bottom:6px; letter-spacing:-0.01em; }
  .modal .desc { color:var(--steel); font-size:13px; margin-bottom:20px; }

  .toast { position:fixed; bottom:26px; right:26px; background:var(--ink); color:var(--paper); padding:13px 20px; border-radius:6px; font-size:13px; opacity:0; transform:translateY(20px); transition:all 0.25s; z-index:300; box-shadow:0 12px 32px rgba(0,0,0,0.25); border-left:3px solid var(--accent); font-family:var(--mono); letter-spacing:0.02em; }
  .toast.show { opacity:1; transform:translateY(0); }
