// =================== DB CRUD ===================
function getDbRecords(dbKey) {
  const db = DATABASES[dbKey];
  if (!db) return [];
  if (db.scope === "global") return state.globalDbs[dbKey] || [];
  if (!state.activeShoppingId) return [];
  return (state.dbs[state.activeShoppingId] && state.dbs[state.activeShoppingId][dbKey]) || [];
}

function saveDbRecords(dbKey, records) {
  const db = DATABASES[dbKey];
  if (db.scope === "global") {
    state.globalDbs[dbKey] = records;
  } else {
    if (!state.dbs[state.activeShoppingId]) state.dbs[state.activeShoppingId] = {};
    state.dbs[state.activeShoppingId][dbKey] = records;
  }
}

function renderDbList(dbKey) {
  const db = DATABASES[dbKey];
  if (!db) return;
  const records = getDbRecords(dbKey);
  const search = (document.getElementById("search-"+dbKey)?.value || "").toLowerCase();
  const filtered = search ? records.filter(r => JSON.stringify(r).toLowerCase().includes(search)) : records;

  const table = document.getElementById("table-"+dbKey);
  document.getElementById("count-"+dbKey).innerHTML = 'Total: <span class="v">'+filtered.length+'</span>'+(records.length !== filtered.length ? ' (de '+records.length+')' : '');

  if (filtered.length === 0) {
    table.innerHTML = '<tr class="empty"><td>Nenhum registro. Clique em "+ Novo registro" para adicionar.</td></tr>';
    return;
  }

  // Selecionar 5-6 colunas principais para exibir
  const displayFields = pickDisplayFields(db);
  let html = '<thead><tr>';
  displayFields.forEach(f => html += '<th>'+escapeHtml(f.label)+'</th>');
  html += '<th></th></tr></thead><tbody>';
  filtered.forEach((r,i) => {
    html += '<tr>';
    displayFields.forEach(f => {
      let v = r[f.key];
      if (Array.isArray(v)) v = v.join(", ");
      if (v === undefined || v === null || v === "") v = '<span style="color:var(--steel)">—</span>';
      // badge para alguns campos
      if (f.key === "presenca_shopping" && v && v !== '<span style="color:var(--steel)">—</span>') {
        const cls = v === "AUSENTE" ? "ausente" : (v.includes("EXISTE") ? "existe" : "nv");
        v = '<span class="db-badge '+cls+'">'+escapeHtml(v)+'</span>';
      } else if (f.key === "status_homol" && v && v !== '<span style="color:var(--steel)">—</span>') {
        v = '<span class="db-badge '+(v === "Homologado" ? "homologado" : "lead")+'">'+escapeHtml(v)+'</span>';
      } else if (f.key === "prioridade" && v && v !== '<span style="color:var(--steel)">—</span>') {
        v = '<span class="db-badge '+v.toLowerCase()+'">'+escapeHtml(v)+'</span>';
      } else if (f.key === "status_produto" && v && v !== '<span style="color:var(--steel)">—</span>') {
        v = '<span class="db-badge '+(v === "Ativo" ? "ativo" : "pausado")+'">'+escapeHtml(v)+'</span>';
      } else if (typeof v === "string" && v.includes("<span")) {
        // já é HTML
      } else {
        v = escapeHtml(String(v));
      }
      html += '<td>'+v+'</td>';
    });
    html += '<td class="actions-cell">';
    html += '<button onclick="editRecord(\''+dbKey+'\',\''+r.id+'\')">Editar</button>';
    html += '<button onclick="deleteRecord(\''+dbKey+'\',\''+r.id+'\')">×</button>';
    html += '</td></tr>';
  });
  html += '</tbody>';
  table.innerHTML = html;
}

function pickDisplayFields(db) {
  // Pega o label_field primeiro + alguns campos importantes
  const result = [];
  const labelKey = db.label_field;
  if (labelKey) {
    const f = db.fields.find(x => x.key === labelKey);
    if (f) result.push(f);
  }
  // Categorias importantes: prioritários
  const priority = ["categoria","tipo","status","status_homol","status_ka","status_abordagem","status_produto","status_lead","presenca_shopping","capital","cidade","bairro","piso","prioridade","categoria_1","raio_km","parceiro"];
  priority.forEach(k => {
    if (result.length >= 6) return;
    const f = db.fields.find(x => x.key === k);
    if (f && !result.includes(f)) result.push(f);
  });
  return result.slice(0, 6);
}

function openRecordModal(dbKey) {
