function editRecord(dbKey, recordId) {
  const records = getDbRecords(dbKey);
  const rec = records.find(r => r.id === recordId);
  if (!rec) return;
  currentRecordEdit = {dbKey, recordId};
  const db = DATABASES[dbKey];
