function buildRecordForm(dbKey, record) {
  const db = DATABASES[dbKey];
  // Agrupar campos por "group"
  const groups = {};
  db.fields.forEach(f => {
    const g = f.group || "Geral";
    if (!groups[g]) groups[g] = [];
    groups[g].push(f);
  });

  let html = '<div class="form-grid">';
  Object.keys(groups).forEach(g => {
    html += '<div class="form-section-title">'+escapeHtml(g)+'</div>';
    groups[g].forEach(f => {
      const fid = "rec_" + dbKey + "_" + f.key;
      const v = record[f.key] !== undefined ? record[f.key] : (f.defaultValue || "");
      const colCls = (f.type === "textarea" || f.type === "multi") ? "full" : "";
      html += '<div class="'+colCls+'"><label>'+escapeHtml(f.label)+
        (f.required ? ' <span class="required">*</span>' : '')+
        (f.hint ? ' <span class="hint">'+escapeHtml(f.hint)+'</span>' : '')+
        '</label>';
      if (f.type === "textarea") {
        html += '<textarea id="'+fid+'" placeholder="'+escapeHtml(f.placeholder||"")+'">'+escapeHtml(v)+'</textarea>';
      } else if (f.type === "select") {
        html += '<select id="'+fid+'"><option value="">—</option>';
        (f.options||[]).forEach(o => {
          html += '<option '+(v === o ? "selected" : "")+'>'+escapeHtml(o)+'</option>';
        });
        html += '</select>';
      } else if (f.type === "multi") {
        const arr = Array.isArray(v) ? v : (v ? [v] : []);
        html += '<div class="pill-group" id="'+fid+'">';
        (f.options||[]).forEach(o => {
          const checked = arr.includes(o);
          html += '<label class="pill-check'+(checked?" checked":"")+'"><input type="checkbox" value="'+escapeHtml(o)+'"'+(checked?" checked":"")+'><span>'+escapeHtml(o)+'</span></label>';
        });
        html += '</div>';
      } else if (f.type === "num") {
        html += '<input type="number" id="'+fid+'" value="'+escapeHtml(v)+'" placeholder="'+escapeHtml(f.placeholder||"")+'">';
      } else if (f.type === "date") {
        html += '<input type="date" id="'+fid+'" value="'+escapeHtml(v)+'">';
      } else if (f.type === "url") {
        html += '<input type="url" id="'+fid+'" value="'+escapeHtml(v)+'" placeholder="'+escapeHtml(f.placeholder||"")+'">';
      } else {
        html += '<input type="text" id="'+fid+'" value="'+escapeHtml(v)+'" placeholder="'+escapeHtml(f.placeholder||"")+'">';
      }
      html += '</div>';
    });
  });
  html += '</div>';
  document.getElementById("recordModalForm").innerHTML = html;
}

async function saveRecord() {
  if (!currentRecordEdit) return;
  const {dbKey, recordId} = currentRecordEdit;
  const db = DATABASES[dbKey];
  const record = recordId ? {...getDbRecords(dbKey).find(r => r.id === recordId)} : {};
  if (!record.id) record.id = "rec_" + Date.now().toString(36) + Math.random().toString(36).substr(2,5);

  db.fields.forEach(f => {
    const fid = "rec_" + dbKey + "_" + f.key;
    if (f.type === "multi") {
      const checks = document.querySelectorAll("#"+fid+" input:checked");
      record[f.key] = Array.from(checks).map(c => c.value);
    } else {
      const el = document.getElementById(fid);
      if (el) record[f.key] = f.type === "num" ? (el.value ? parseFloat(el.value) : "") : el.value;
    }
  });

  // Validar required
  const missing = db.fields.filter(f => f.required && !record[f.key]).map(f => f.label);
  if (missing.length > 0) {
    toast("Campos obrigatórios: " + missing.join(", "));
    return;
  }

  const records = getDbRecords(dbKey);
  if (recordId) {
    const idx = records.findIndex(r => r.id === recordId);
    if (idx >= 0) records[idx] = record;
  } else {
    records.push(record);
  }
  saveDbRecords(dbKey, records);
  await saveState();
  closeRecordModal();
  renderDbList(dbKey);
  renderDbsNav();
  toast(recordId ? "Atualizado" : "Adicionado");
}

async function deleteRecord(dbKey, recordId) {
  if (!confirm("Excluir este registro?")) return;
  const records = getDbRecords(dbKey).filter(r => r.id !== recordId);
  saveDbRecords(dbKey, records);
  await saveState();
  renderDbList(dbKey);
  renderDbsNav();
  toast("Excluído");
}

function deleteCurrentRecord() {
  if (!currentRecordEdit || !currentRecordEdit.recordId) return;
