function buildDbInjection(dbKeys) {
  if (!dbKeys || dbKeys.length === 0) return "";
  let txt = "\n\n==================================================\nBASES DE DADOS INJETADAS\n==================================================\n";
  dbKeys.forEach(dbKey => {
    const db = DATABASES[dbKey];
    if (!db) return;
    const records = getDbRecords(dbKey);
    txt += "\n### "+db.title+" ("+records.length+" registros · "+db.scope+")\n";
    if (records.length === 0) {
      txt += "(base vazia — sem registros cadastrados ainda)\n";
      return;
    }
    // Lista compacta
    records.slice(0, 30).forEach((r,i) => {
      txt += "\n["+(i+1)+"] ";
      // Mostrar campos não vazios
      const parts = [];
      db.fields.forEach(f => {
        const v = r[f.key];
        if (v && v !== "" && (!Array.isArray(v) || v.length > 0)) {
          const dispV = Array.isArray(v) ? v.join("/") : v;
          parts.push(f.label+": "+dispV);
        }
      });
      txt += parts.join(" | ");
    });
    if (records.length > 30) txt += "\n... e mais "+(records.length-30)+" registros";
  });
  txt += "\n==================================================";
  return txt;
}

function getDbsForSection(sectionId) {
  if (sectionId === "wf1") return ["pontos_vagos","plano_mix","marcas","hunter_targets","investidores"];
