    '<div style="display:flex;gap:6px;">' +
    '<button class="btn" style="padding:6px 12px;font-size:11px;" onclick="showHistoryItem('+(state.history.length-1-i)+')">Ver</button>' +
    '</div></div>'
  ).join("");
}

function showHistoryItem(idx) {
  const h = state.history[idx];
