    '<div class="actions-mini"><button onclick="copyOutput(this)">Copiar</button>' +
    '<button onclick="this.closest(\'.output-block\').remove()">Fechar</button></div></div>' +
    '<div class="output-content">' + renderMarkdown(h.output || "(sem output)") + '</div>';
  wrap.appendChild(ob);
  ob.scrollIntoView({behavior:"smooth"});
}

