  .output-block { background:white; border:1px solid var(--rule-soft); border-radius:8px; padding:0; overflow:hidden; margin-top:20px; }
  .output-bar { background:var(--ink); color:var(--paper); padding:11px 16px; display:flex; justify-content:space-between; align-items:center; }
  .output-bar .label { font-family:var(--mono); font-size:10px; letter-spacing:0.15em; color:var(--gold); text-transform:uppercase; }
  .output-bar .actions-mini { display:flex; gap:5px; }
  .output-bar button { background:var(--ink-soft); color:var(--paper); border:1px solid var(--rule); padding:5px 10px; border-radius:3px; font-size:11px; font-family:var(--mono); cursor:pointer; }
  .output-bar button:hover { background:var(--rule); }

  .output-content { padding:26px 30px; font-family:var(--body); font-size:14px; line-height:1.7; color:var(--ink); max-height:700px; overflow-y:auto; }
  .output-content h1,.output-content h2,.output-content h3 { font-family:var(--display); font-weight:700; margin:18px 0 8px; line-height:1.2; }
  .output-content h1 { font-size:24px; }
  .output-content h2 { font-size:19px; color:var(--accent); border-bottom:1px solid var(--rule-soft); padding-bottom:6px; }
  .output-content h3 { font-size:16px; }
  .output-content p { margin-bottom:10px; }
  .output-content ul,.output-content ol { margin:8px 0 12px 24px; }
  .output-content li { margin-bottom:4px; }
  .output-content table { border-collapse:collapse; margin:12px 0; font-size:12px; width:100%; }
  .output-content th,.output-content td { border:1px solid var(--rule-soft); padding:8px 10px; text-align:left; vertical-align:top; }
  .output-content th { background:var(--paper); font-weight:600; }
  .output-content code { background:var(--paper); padding:2px 6px; border-radius:3px; font-family:var(--mono); font-size:12px; }
  .output-content strong { color:var(--ink); font-weight:700; }
  .output-content em { color:var(--accent); font-style:italic; }

  .streaming-indicator { display:inline-flex; align-items:center; gap:6px; color:var(--accent); font-family:var(--mono); font-size:11px; }
  .streaming-indicator .pulse { width:8px; height:8px; background:var(--accent); border-radius:50%; animation:pulse 1.4s infinite; }
  @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }

  .cost-estimate { background:var(--paper-soft); border-left:3px solid var(--gold); padding:10px 14px; border-radius:0 4px 4px 0; font-size:12px; margin-top:12px; font-family:var(--mono); color:var(--ink-soft); }

  .stats-bar { display:flex; gap:16px; padding:10px 18px; background:var(--paper-soft); border-top:1px solid var(--rule-soft); font-family:var(--mono); font-size:11px; color:var(--steel); flex-wrap:wrap; }
  .stats-bar .stat .v { color:var(--ink); font-weight:700; }

  .hero-grid { display:grid; grid-template-columns:2fr 1fr; gap:18px; margin-bottom:28px; }
  .hero-main { background:var(--ink); color:var(--paper); border-radius:8px; padding:34px 30px; position:relative; overflow:hidden; }
  .hero-main::before { content:""; position:absolute; top:-40px; right:-40px; width:200px; height:200px; background:radial-gradient(circle,var(--accent) 0%,transparent 70%); opacity:0.3; }
  .hero-main h1 { font-family:var(--display); font-weight:900; font-size:36px; line-height:0.95; letter-spacing:-0.03em; margin-bottom:14px; position:relative; }
  .hero-main h1 em { font-style:italic; font-weight:500; color:var(--accent-2); }
  .hero-main p { font-size:15px; color:var(--paper-soft); max-width:480px; line-height:1.6; position:relative; }
  .hero-side { background:var(--paper-soft); border-radius:8px; padding:22px; border:1px solid var(--rule-soft); }
  .hero-side h3 { font-family:var(--mono); font-size:10px; letter-spacing:0.18em; text-transform:uppercase; color:var(--steel); margin-bottom:12px; }
  .hero-side ul { list-style:none; }
  .hero-side li { padding:9px 0; border-top:1px solid var(--rule-soft); font-size:13px; display:flex; justify-content:space-between; align-items:center; }
  .hero-side li:first-child { border-top:none; }
  .hero-side li .num { font-family:var(--mono); font-weight:700; font-size:15px; color:var(--accent); }

  .grid-3 { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
  .grid-4 { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; }

  .wf-card,.db-card,.agent-mini { background:white; border:1px solid var(--rule-soft); border-radius:8px; padding:20px; cursor:pointer; transition:all 0.2s; }
  .wf-card:hover,.db-card:hover,.agent-mini:hover { border-color:var(--ink); transform:translateY(-2px); box-shadow:0 8px 24px -4px rgba(13,17,23,0.15); }
  .wf-card .wf-num,.db-card .db-num { font-family:var(--mono); font-size:32px; font-weight:700; color:var(--rule-soft); line-height:1; margin-bottom:6px; }
  .wf-card:hover .wf-num,.db-card:hover .db-num { color:var(--accent); }
  .db-card .db-icon { font-family:var(--display); font-size:28px; color:var(--moss); line-height:1; margin-bottom:6px; }
  .wf-card h4,.db-card h4 { font-family:var(--display); font-weight:700; font-size:18px; line-height:1.15; margin-bottom:7px; letter-spacing:-0.01em; }
  .wf-card p,.db-card p { font-size:12px; color:var(--steel); line-height:1.5; }
  .db-card .db-stats { margin-top:12px; display:flex; gap:12px; font-family:var(--mono); font-size:10px; color:var(--moss); }
  .db-card .db-stats .v { font-weight:700; color:var(--accent); }

  .agent-mini { padding:12px; }
  .agent-mini .num { font-family:var(--mono); font-size:10px; color:var(--gold); margin-bottom:4px; }
  .agent-mini .name { font-weight:600; font-size:12px; line-height:1.2; margin-bottom:3px; }
  .agent-mini .desc { font-size:10.5px; color:var(--steel); line-height:1.4; }

  /* MODAL */
  .modal-bg { display:none; position:fixed; inset:0; background:rgba(13,17,23,0.7); z-index:200; justify-content:center; align-items:center; backdrop-filter:blur(4px); padding:20px; }
  .modal-bg.active { display:flex; }
  .modal { background:var(--paper); border-radius:12px; padding:28px; width:100%; max-width:680px; box-shadow:0 20px 60px rgba(0,0,0,0.4); max-height:90vh; overflow-y:auto; }
  .modal.wide { max-width:920px; }
  .modal h2 { font-family:var(--display); font-size:24px; font-weight:700; margin-bottom:6px; letter-spacing:-0.01em; }
  .modal .desc { color:var(--steel); font-size:13px; margin-bottom:20px; }

  .toast { position:fixed; bottom:26px; right:26px; background:var(--ink); color:var(--paper); padding:13px 20px; border-radius:6px; font-size:13px; opacity:0; transform:translateY(20px); transition:all 0.25s; z-index:300; box-shadow:0 12px 32px rgba(0,0,0,0.25); border-left:3px solid var(--accent); font-family:var(--mono); letter-spacing:0.02em; }
  .toast.show { opacity:1; transform:translateY(0); }
  .toast.error { background:#4a1a14; }

  .ornament { text-align:center; margin:22px 0; color:var(--rule-soft); font-family:var(--display); font-size:16px; letter-spacing:0.5em; }
  .banner { background:var(--paper-soft); border-left:3px solid var(--gold); padding:13px 17px; border-radius:0 6px 6px 0; font-size:13px; margin-bottom:18px; }
  .banner.warn { border-left-color:var(--accent); background:#fdf0ec; }
  .banner.info { border-left-color:var(--moss); }
  .banner strong { color:var(--accent); }

  .section { display:none; animation:fadeIn 0.3s; }
  .section.active { display:block; }
  @keyframes fadeIn { from { opacity:0; transform:translateY(8px); } to { opacity:1; transform:translateY(0); } }

  .help-text { font-size:11px; color:var(--steel); margin-top:5px; font-family:var(--mono); line-height:1.5; }
  .help-text a { color:var(--accent); }

  .injection-info { background:var(--paper-soft); border:1px dashed var(--moss); border-radius:6px; padding:12px 16px; margin:10px 0 16px; font-size:12px; }
  .injection-info .title { font-family:var(--mono); font-size:10px; letter-spacing:0.12em; text-transform:uppercase; color:var(--moss); font-weight:700; margin-bottom:6px; }
  .injection-info .list { display:flex; flex-wrap:wrap; gap:6px; }
  .injection-info .chip { background:white; padding:3px 9px; border-radius:8px; font-size:11px; border:1px solid var(--rule-soft); }
  .injection-info .chip .n { color:var(--accent); font-weight:700; }

  @media (max-width:1024px) {
    .app { grid-template-columns:1fr; }
    .sidebar { position:relative; height:auto; }
    main { padding:20px; }
    .hero-grid,.grid-3,.grid-4 { grid-template-columns:1fr; }
    .form-grid { grid-template-columns:1fr; }
    h1.page-title { font-size:30px; }
  }
</style>
</head>
<body>

<div class="app">

<aside class="sidebar">
  <div class="brand">
    <div class="mark">Shopping<span class="dot">.</span>OS</div>
    <div class="sub">v5 · Console v2 · Bases integradas</div>
  </div>

  <div class="api-status" id="apiStatusBox" onclick="openApiModal()">
    <span class="dot-led" id="apiLed"></span>
    <span class="label" id="apiStatusLabel">API não configurada</span>
    <span style="color:var(--steel);">⚙</span>
  </div>

  <div class="shopping-switcher">
    <div class="label">Shopping ativo</div>
    <select id="shoppingSelect" onchange="changeShopping(this.value)"></select>
    <div class="meta" id="shoppingMeta"></div>
    <button class="new" onclick="openShoppingModal()">+ Novo shopping</button>
  </div>

  <nav>
    <div class="nav-group">
      <div class="group-label">Início</div>
      <div class="nav-item active" data-section="home" onclick="navigate('home')"><span class="num">⌂</span><span>Console</span></div>
      <div class="nav-item" data-section="shopping" onclick="navigate('shopping')"><span class="num">⊕</span><span>Perfil do Shopping</span></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Bases de Dados</div>
      <div id="dbsNav"></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Workflows</div>
      <div class="nav-item workflow" data-section="wf1" onclick="navigate('wf1')"><span class="num">W1</span><span>Vacancy-to-Contract</span></div>
      <div class="nav-item workflow" data-section="wf2" onclick="navigate('wf2')"><span class="num">W2</span><span>Street-to-Shopping</span></div>
      <div class="nav-item workflow" data-section="wf3" onclick="navigate('wf3')"><span class="num">W3</span><span>Cluster Experience</span></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Agentes</div>
      <div id="agentsNav"></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Sistema</div>
      <div class="nav-item" data-section="history" onclick="navigate('history')"><span class="num">⌖</span><span>Histórico</span></div>
      <div class="nav-item" data-section="data" onclick="navigate('data')"><span class="num">⇄</span><span>Export / Import</span></div>
    </div>
  </nav>
</aside>


<main>

<!-- HOME -->
<section id="home" class="section active">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Console</span></div>
  <div class="hero-grid">
    <div class="hero-main">
      <h1>Onde<br>oportunidade<br><em>vira contrato.</em></h1>
      <p>Sistema completo de gestão comercial multi-shopping. 7 bases de dados estruturadas alimentam 16 agentes Claude que retornam análises acionáveis via API.</p>
    </div>
    <div class="hero-side">
      <h3>Atividade do shopping ativo</h3>
      <ul>
        <li>Execuções <span class="num" id="cntExecutions">0</span></li>
        <li>Tokens <span class="num" id="cntTokens" style="font-family:var(--mono);font-size:13px;">0</span></li>
        <li>Custo total <span class="num" id="cntCost" style="font-family:var(--mono);font-size:13px;">$0.00</span></li>
      </ul>
    </div>
  </div>

  <div id="apiWarning" class="banner warn" style="display:none;">
    <strong>API não configurada.</strong> Configure sua chave Anthropic para executar agentes via API.
  </div>

  <div class="ornament">· · ·</div>

  <h2 style="font-family:var(--display);font-size:26px;font-weight:700;margin-bottom:4px;letter-spacing:-0.01em;">Bases de Dados</h2>
  <p style="color:var(--steel);font-size:13px;margin-bottom:18px;">7 bases estruturadas que alimentam os agentes automaticamente.</p>
  <div class="grid-4" id="homeDbsGrid"></div>

  <div class="ornament">· · ·</div>

  <h2 style="font-family:var(--display);font-size:26px;font-weight:700;margin-bottom:4px;letter-spacing:-0.01em;">Workflows Prioritários</h2>
  <p style="color:var(--steel);font-size:13px;margin-bottom:18px;">Os 3 sprints orquestrados do v5.</p>
  <div class="grid-3">
    <div class="wf-card" onclick="navigate('wf1')">
      <div class="wf-num">01</div><h4>Vacancy-to-Contract Sprint</h4>
      <p>Reduz vacância e encurta ciclo vaga → contrato.</p>
    </div>
    <div class="wf-card" onclick="navigate('wf2')">
      <div class="wf-num">02</div><h4>Street-to-Shopping</h4>
      <p>Converte operadores de rua em lojistas.</p>
    </div>
    <div class="wf-card" onclick="navigate('wf3')">
      <div class="wf-num">03</div><h4>Cluster Experience Growth</h4>
      <p>Frequência, ticket e experiência.</p>
    </div>
  </div>

  <div class="ornament">· · ·</div>

  <h2 style="font-family:var(--display);font-size:26px;font-weight:700;margin-bottom:4px;letter-spacing:-0.01em;">Agentes Individuais</h2>
  <p style="color:var(--steel);font-size:13px;margin-bottom:18px;">16 agentes especializados. Cada um recebe as bases relevantes automaticamente.</p>
  <div class="grid-4" id="homeAgentsGrid"></div>
</section>


<!-- PERFIL DO SHOPPING -->
<section id="shopping" class="section">
  <div class="breadcrumb">CADASTRO <span class="sep">/</span> <span class="current">Perfil do Shopping</span></div>
  <h1 class="page-title">Perfil do Shopping</h1>
  <p class="page-desc">Define o contexto que <strong>todos os agentes e bases</strong> usam.</p>

  <div class="card">
    <h2>Identificação</h2>
    <div class="form-grid">
      <div class="full"><label>Nome do shopping <span class="required">*</span></label><input type="text" id="sh_nome"></div>
      <div><label>Cidade <span class="required">*</span></label><input type="text" id="sh_cidade"></div>
      <div><label>Estado</label><input type="text" id="sh_estado"></div>
      <div class="full"><label>Endereço</label><input type="text" id="sh_endereco"></div>
      <div>
        <label>Cluster <span class="required">*</span></label>
        <select id="sh_cluster">
          <option value="">— selecione —</option>
          <option>Sofisticados</option><option>Compactos de Alto Padrão</option>
          <option>Entretenimento</option><option>Passeio Familiar</option>
          <option>Imensos</option><option>Convenientes</option>
        </select>
      </div>
      <div><label>Operador</label><input type="text" id="sh_operador"></div>
    </div>
  </div>

  <div class="card">
    <h2>Métricas físicas</h2>
    <div class="form-grid">
      <div><label>ABL total (m²)</label><input type="number" id="sh_abl"></div>
      <div><label>Total de lojas</label><input type="number" id="sh_lojas"></div>
      <div><label>Inauguração</label><input type="number" id="sh_ano"></div>
      <div><label>Última reforma</label><input type="number" id="sh_reforma"></div>
      <div><label>Vacância atual (%)</label><input type="number" id="sh_vacancia" min="0" max="100"></div>
      <div><label>ABL vaga (m²)</label><input type="number" id="sh_abl_vaga"></div>
    </div>
  </div>

  <div class="card">
    <h2>Posicionamento e diagnóstico</h2>
    <div class="form-grid">
      <div class="full">
        <label>Batalhas prioritárias <span class="hint">selecione 2-4</span></label>
        <div class="pill-group" id="sh_batalhas_group">
          <label class="pill-check"><input type="checkbox" value="Lojas"><span>Lojas</span></label>
          <label class="pill-check"><input type="checkbox" value="Gastronomia"><span>Gastronomia</span></label>
          <label class="pill-check"><input type="checkbox" value="Entretenimento"><span>Entretenimento</span></label>
          <label class="pill-check"><input type="checkbox" value="Hospitality"><span>Hospitality</span></label>
          <label class="pill-check"><input type="checkbox" value="Serviços"><span>Serviços</span></label>
          <label class="pill-check"><input type="checkbox" value="Ambiência"><span>Ambiência</span></label>
          <label class="pill-check"><input type="checkbox" value="Entorno"><span>Entorno</span></label>
          <label class="pill-check"><input type="checkbox" value="Jornada sem fricção"><span>Jornada sem fricção</span></label>
        </div>
      </div>
      <div class="full"><label>Target principal</label><textarea id="sh_target"></textarea></div>
      <div class="full"><label>Concorrência direta</label><textarea id="sh_concorrencia"></textarea></div>
      <div class="full"><label>Pontos fortes</label><textarea id="sh_fortes"></textarea></div>
      <div class="full"><label>Lacunas de mix</label><textarea id="sh_lacunas"></textarea></div>
      <div class="full"><label>Lojas em saída/risco</label><textarea id="sh_saidas"></textarea></div>
      <div class="full"><label>Mix atual (lista) <span class="hint">filtro duplicidade</span></label><textarea id="sh_mix" placeholder="Cole a lista de marcas atuais"></textarea></div>
    </div>
    <div class="actions">
      <button class="btn btn-primary" onclick="saveShopping()">Salvar perfil</button>
      <button class="btn btn-danger" onclick="confirmDeleteShopping()">Excluir shopping</button>
      <span style="margin-left:auto;color:var(--steel);font-size:12px;" id="shoppingSaveStatus"></span>
    </div>
  </div>
</section>

<!-- Bases de Dados, Workflows e Agentes são gerados via JS -->
<div id="dynamicSections"></div>


<!-- HISTÓRICO -->
<section id="history" class="section">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Histórico</span></div>
  <h1 class="page-title">Histórico de Execuções</h1>
  <p class="page-desc">Últimas 50 execuções de agentes e workflows.</p>
  <div class="card" style="padding:0;">
    <div id="historyList" style="max-height:700px;overflow-y:auto;"></div>
  </div>
</section>


<!-- DADOS -->
<section id="data" class="section">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Export / Import</span></div>
  <h1 class="page-title">Dados</h1>
  <p class="page-desc">Backup completo de shoppings + bases + histórico.</p>
  <div class="card">
    <h2>Exportar</h2>
    <p class="card-desc">JSON com todos os dados.</p>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn btn-primary" onclick="exportAll()">Exportar tudo</button>
      <button class="btn" onclick="exportCurrentShopping()">Exportar shopping ativo</button>
      <button class="btn" onclick="exportDBCSV()">Exportar base ativa em CSV</button>
    </div>
  </div>
  <div class="card">
    <h2>Importar</h2>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn btn-primary" onclick="importAll()">Importar JSON</button>
    </div>
  </div>
  <div class="card">
    <h2 style="color:var(--accent);">Zona de risco</h2>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn btn-danger" onclick="clearAllData()">Apagar tudo</button>
    </div>
  </div>
</section>

</main>
</div>


<!-- MODAL: API -->
<div class="modal-bg" id="modalApi">
  <div class="modal">
    <h2>Configurar API Anthropic</h2>
    <p class="desc">Cole sua chave. Fica salva apenas no seu navegador.</p>
    <div class="banner warn"><strong>Segurança:</strong> não use em máquinas compartilhadas. Para produção, use proxy backend.</div>
    <div style="display:grid;gap:14px;">
      <div>
        <label>Chave de API <span class="required">*</span></label>
        <input type="password" id="apiKeyInput" placeholder="sk-ant-...">
        <div class="help-text">Crie em <a href="https://console.anthropic.com/settings/keys" target="_blank">console.anthropic.com/settings/keys</a></div>
      </div>
      <div>
        <label>Modelo</label>
        <select id="apiModel">
          <option value="claude-sonnet-4-6-20250929" selected>Claude Sonnet 4.6 (recomendado)</option>
          <option value="claude-opus-4-7-20251201">Claude Opus 4.7 (mais caro, melhor)</option>
          <option value="claude-haiku-4-5-20251001">Claude Haiku 4.5 (rápido, barato)</option>
        </select>
      </div>
      <div>
        <label>Web Search</label>
        <select id="apiWebSearch">
          <option value="true" selected>Habilitado (recomendado)</option>
          <option value="false">Desabilitado</option>
        </select>
      </div>
      <div>
        <label>Max tokens</label>
        <input type="number" id="apiMaxTokens" value="8000" min="1000" max="16000">
      </div>
    </div>
    <div class="actions" style="margin-top:22px;padding-top:16px;">
      <button class="btn btn-primary" onclick="saveApiConfig()">Salvar e testar</button>
      <button class="btn btn-danger" onclick="clearApiKey()">Remover chave</button>
      <button class="btn btn-ghost" onclick="closeApiModal()">Cancelar</button>
    </div>
  </div>
</div>

<!-- MODAL: NOVO SHOPPING -->
<div class="modal-bg" id="modalShopping">
  <div class="modal">
    <h2>Novo shopping</h2>
    <p class="desc">Cadastre um shopping.</p>
    <div style="display:grid;gap:14px;">
      <div><label>Nome <span class="required">*</span></label><input type="text" id="newSh_nome"></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <div><label>Cidade <span class="required">*</span></label><input type="text" id="newSh_cidade"></div>
        <div><label>Estado</label><input type="text" id="newSh_estado"></div>
      </div>
      <div>
