        "Content-Type":"application/json","x-api-key":apiConfig.key,
        "anthropic-version":"2023-06-01",
        "anthropic-dangerous-direct-browser-access":"true"
      },
      body:JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message || "Erro API");
    const text = (data.content || []).filter(b => b.type === "text").map(b => b.text).join("\n\n");
    const elapsed = ((Date.now() - startTime)/1000).toFixed(1);
    const usage = data.usage || {};
    const cost = calculateCost(usage, apiConfig.model);

    state.history.push({
      ts: Date.now(), shoppingId: s.id, shoppingNome: s.nome,
      type: built.type, sectionId, label: built.label,
      prompt: built.prompt, output: text, usage, cost, elapsed,
      model: apiConfig.model, webSearchUsed: apiConfig.webSearch
    });
    if (state.history.length > 50) state.history = state.history.slice(-50);
    await saveState();

    outputBlock.querySelector(".output-content").innerHTML = renderMarkdown(text);

    const stats = document.createElement("div");
    stats.className = "stats-bar";
    stats.innerHTML =
      '<span class="stat">Modelo: <span class="v">'+apiConfig.model.split("-").slice(1,3).join(" ")+'</span></span>' +
      '<span class="stat">Tokens in: <span class="v">'+(usage.input_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tokens out: <span class="v">'+(usage.output_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tempo: <span class="v">'+elapsed+'s</span></span>' +
      '<span class="stat">Custo: <span class="v">$'+cost.toFixed(3)+'</span></span>';
    outputBlock.appendChild(stats);
    toast("✓ Concluído em " + elapsed + "s");
    renderHome();
  } catch(e) {
    outputBlock.querySelector(".output-content").innerHTML =
      '<div style="color:var(--accent);padding:20px;"><strong>Erro:</strong> ' + escapeHtml(e.message) + '</div>';
    toast("Erro: " + e.message, "error");
  } finally {
    btn.disabled = false;
    btn.innerHTML = origText;
  }
}

function calculateCost(usage, model) {
  const p = PRICING[model] || PRICING["claude-sonnet-4-6-20250929"];
  return (usage.input_tokens || 0) / 1e6 * p.input + (usage.output_tokens || 0) / 1e6 * p.output;
}

// =================== MARKDOWN ===================
function renderMarkdown(text) {
  if (!text) return "";
  let h = escapeHtml(text);
  h = h.replace(/^### (.+)$/gm, '<h3>$1</h3>')
       .replace(/^## (.+)$/gm, '<h2>$1</h2>')
       .replace(/^# (.+)$/gm, '<h1>$1</h1>')
       .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
       .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
       .replace(/(^|[^*])\*([^*\n]+)\*([^*]|$)/g, '$1<em>$2</em>$3')
       .replace(/`([^`]+)`/g, '<code>$1</code>');
  h = h.replace(/(\|.+\|\n\|[\s\-:|]+\|\n(?:\|.+\|\n?)+)/g, m => {
    const lines = m.trim().split("\n");
    const head = lines[0].split("|").slice(1,-1).map(c => '<th>'+c.trim()+'</th>').join("");
    const rows = lines.slice(2).map(l => '<tr>' + l.split("|").slice(1,-1).map(c => '<td>'+c.trim()+'</td>').join("") + '</tr>').join("");
    return '<table><thead><tr>'+head+'</tr></thead><tbody>'+rows+'</tbody></table>';
  });
  h = h.replace(/^(\s*)([-*+]) (.+)$/gm, '$1<li>$3</li>')
       .replace(/(<li>.*<\/li>\n?)+/g, m => '<ul>'+m+'</ul>')
       .replace(/^(\s*)\d+\. (.+)$/gm, '$1<oli>$2</oli>')
       .replace(/(<oli>.*<\/oli>\n?)+/g, m => '<ol>'+m.replace(/oli/g,"li")+'</ol>');
  h = h.split(/\n\n+/).map(p => {
    if (p.match(/^<(h\d|ul|ol|table|li)/)) return p;
    return '<p>'+p.replace(/\n/g,"<br>")+'</p>';
  }).join("\n");
  return h;
}

// =================== HISTORY / EXPORT ===================
function renderHistory() {
  const wrap = document.getElementById("historyList");
  if (state.history.length === 0) {
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:var(--steel);font-style:italic;">Nenhuma execução ainda.</div>';
    return;
  }
  wrap.innerHTML = state.history.slice().reverse().map((h,i) =>
    '<div style="padding:16px 20px;border-bottom:1px solid var(--rule-soft);display:flex;justify-content:space-between;align-items:center;gap:12px;">' +
    '<div style="flex:1;"><div style="font-weight:600;font-size:14px;margin-bottom:2px;">' + escapeHtml(h.label) + '</div>' +
    '<div style="color:var(--steel);font-size:11px;font-family:var(--mono);">' + escapeHtml(h.shoppingNome) + ' · ' + new Date(h.ts).toLocaleString("pt-BR") + ' · $' + (h.cost||0).toFixed(3) + '</div></div>' +
    '<div style="display:flex;gap:6px;">' +
    '<button class="btn" style="padding:6px 12px;font-size:11px;" onclick="showHistoryItem('+(state.history.length-1-i)+')">Ver</button>' +
    '</div></div>'
  ).join("");
}

function showHistoryItem(idx) {
  const h = state.history[idx];
  if (!h) return;
  const wrap = document.getElementById("historyList").parentElement;
  let exist = wrap.querySelector(".output-block.hist");
  if (exist) exist.remove();
  const ob = document.createElement("div");
  ob.className = "output-block hist";
  ob.style.marginTop = "16px";
  ob.innerHTML =
    '<div class="output-bar"><span class="label">▸ ' + escapeHtml(h.label) + ' · ' + escapeHtml(h.shoppingNome) + '</span>' +
    '<div class="actions-mini"><button onclick="copyOutput(this)">Copiar</button>' +
    '<button onclick="this.closest(\'.output-block\').remove()">Fechar</button></div></div>' +
    '<div class="output-content">' + renderMarkdown(h.output || "(sem output)") + '</div>';
  wrap.appendChild(ob);
  ob.scrollIntoView({behavior:"smooth"});
}

function copyOutput(btn) {
  const text = btn.closest(".output-block").querySelector(".output-content").innerText;
  navigator.clipboard.writeText(text);
  toast("Copiado");
}
function downloadOutput(btn) {
  const text = btn.closest(".output-block").querySelector(".output-content").innerText;
  const blob = new Blob([text], {type:"text/markdown"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "analise-" + new Date().toISOString().slice(0,10) + ".md";
  a.click();
}
function downloadPrompt(sectionId) {
  const built = buildPromptForSection(sectionId);
  if (!built) return;
  downloadPromptText(built.prompt, built.label);
}
function downloadPromptText(text, label) {
  const cur = state.shoppings[state.activeShoppingId];
  const blob = new Blob([text], {type:"text/plain"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "prompt-" + (cur?cur.nome:"shopping").toLowerCase().replace(/[^a-z0-9]/g,"-") + "-" + label.toLowerCase().replace(/[^a-z0-9]/g,"-") + ".txt";
  a.click();
  toast("Prompt baixado");
}

function exportAll() {
  const blob = new Blob([JSON.stringify(state, null, 2)], {type:"application/json"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "shopping-os-backup-" + new Date().toISOString().slice(0,10) + ".json";
  a.click();
  toast("Backup exportado");
}
function exportCurrentShopping() {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) return;
  const data = {shopping: s, dbs: state.dbs[s.id], history: state.history.filter(h => h.shoppingId === s.id)};
  const blob = new Blob([JSON.stringify(data, null, 2)], {type:"application/json"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = s.nome.toLowerCase().replace(/[^a-z0-9]/g,"-") + ".json";
  a.click();
}
function exportDBCSV() {
  const active = document.querySelector(".section.active");
  if (!active || !active.id.startsWith("db-")) { toast("Abra uma base de dados primeiro"); return; }
  const dbKey = active.id.replace("db-","");
  const db = DATABASES[dbKey];
  const records = getDbRecords(dbKey);
  if (records.length === 0) { toast("Base vazia"); return; }
  const headers = db.fields.map(f => f.label);
  const keys = db.fields.map(f => f.key);
  const rows = records.map(r => keys.map(k => {
    let v = r[k] || "";
    if (Array.isArray(v)) v = v.join("/");
    v = String(v).replace(/"/g, '""');
    return '"' + v + '"';
  }).join(";"));
  const csv = headers.map(h => '"' + h + '"').join(";") + "\n" + rows.join("\n");
  const blob = new Blob(["\ufeff" + csv], {type:"text/csv;charset=utf-8"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = dbKey + "-" + new Date().toISOString().slice(0,10) + ".csv";
  a.click();
  toast("CSV exportado");
}
function importAll() {
  const input = document.createElement("input");
  input.type = "file"; input.accept = "application/json";
  input.onchange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    try {
      const data = JSON.parse(await file.text());
      if (!confirm("Importar substitui o estado atual. Continuar?")) return;
      state = data;
      await saveState();
      renderShoppingSwitcher();
      renderHome();
      renderDbsNav();
      toast("Importado");
    } catch(e) { toast("Erro: " + e.message, "error"); }
  };
  input.click();
}
async function clearAllData() {
  if (!confirm("APAGAR TUDO?")) return;
  if (!confirm("Confirma?")) return;
  state = {shoppings:{}, activeShoppingId:null, history:[], drafts:{}, dbs:{}, globalDbs:{}};
  await saveState();
  await loadState();
  renderShoppingSwitcher();
  renderHome();
  renderDbsNav();
  navigate("home");
  toast("Limpo");
}

// =================== DRAFTS ===================
function loadDraft(sectionId) {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) return;
  const draft = state.drafts[s.id+"::"+sectionId];
  if (!draft) return;
  Object.keys(draft).forEach(k => {
    const el = document.getElementById(k);
    if (el) el.value = draft[k];
  });
