    executionBlock = "Workflow: "+label+"\n" +
      "Objetivo: "+getVal("wf3_obj")+"\n" +
      "Espaços: "+(getVal("wf3_espacos") || "n.v.")+"\n" +
      "Sazonalidades: "+(getVal("wf3_datas") || "n.v.")+"\n" +
      "Lacunas: "+(getVal("wf3_gaps") || "n.v.")+" | Orçamento: "+(getVal("wf3_orcamento") || "n.v.");
  } else if (sectionId.startsWith("agent-")) {
    const id = parseInt(sectionId.replace("agent-",""));
    const agent = AGENTS.find(a => a.id === id);
    type = "agent"; label = agent.name;
    const params = (agent.fields||[]).map(f => f.label+": "+(getVal("agent"+agent.id+"_"+f.key) || "n.v.")).join("\n");
    executionBlock = "Agente: "+String(agent.id).padStart(2,"0")+" · "+agent.name+" ("+agent.category+")\n" +
      "Descrição: "+agent.desc+"\n\nParâmetros:\n"+params;
  } else return null;

  const dbInjection = buildDbInjection(getDbsForSection(sectionId));

  // PROMPT OTIMIZADO - regras concisas + instrução ADD_TO_DB explícita
  const prompt = buildShoppingHeader() + dbInjection +
    "\n\n## EXECUÇÃO\n" + executionBlock +
    "\n\n## REGRAS v5 (siga estritamente)\n" +
    "1. Cluster First: use cluster e batalhas acima como filtro.\n" +
    "2. Filtro de duplicidade OBRIGATÓRIO: NÃO sugerir marcas no Mix atual.\n" +
    "3. Cluster Fit (0-40 não, 41-70 aceitável, 71-85 forte, 86-100 estratégico).\n" +
    "4. Use as bases injetadas como fonte primária.\n" +
    "5. Use web search para validar status quando relevante.\n" +
    "6. Dados não verificáveis: marcar \"n.v.\". Nunca inventar.\n" +
    "7. Para cada recomendação: problema econômico, batalha, dono, prazo, impacto, KPI.\n" +
    "8. Confiança (1-10) ao final + ressalvas.\n" +
    "\n## AUTO-CADASTRO (importante)\n" +
    "Sempre que sugerir uma nova entidade (marca, investidor, ponto, etc), ADICIONE no final do output um bloco assim:\n" +
    "```ADD_TO_DB:<dbKey>\n" +
    "{\"campo1\":\"valor\",\"campo2\":\"valor\",...}\n" +
    "```\n" +
    "Use os dbKeys: pontos_vagos, investidores, marcas, plano_mix, fornecedores, hunter_targets, produtos_fin.\n" +
    "Inclua os campos relevantes que conseguiu identificar (não precisa todos). Um bloco por sugestão. Os campos disponíveis em cada base estão listados na seção BASES acima.\n" +
    "\n## FORMATO DE SAÍDA\n" +
    "Markdown. Headings com ##. Tabelas quando útil. Resumo executivo no início. Cada workflow/agente: saída padrão v5 (diagnóstico, oportunidades em tabela, plano 30/60/90, KPIs, riscos, próxima ação por dono).";

  return {prompt, label, type};
}

function getVal(id) { const el = document.getElementById(id); return el ? el.value.trim() : ""; }

// =================== EXECUTION ===================
async function executeBriefing(sectionId) {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) { toast("Selecione um shopping", "error"); return; }
  if (!s.cluster) { toast("Defina o cluster", "error"); navigate("shopping"); return; }

  const built = buildPromptForSection(sectionId);
  if (!built) return;

  if (!apiConfig.key) {
    if (confirm("API não configurada. Baixar prompt para colar manualmente?")) {
      downloadPromptText(built.prompt, built.label);
    } else openApiModal();
    return;
  }

  const btn = document.getElementById("btn-" + sectionId);
  const origText = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="streaming-indicator"><span class="pulse"></span>Executando...</span>';

  const section = document.getElementById(sectionId);
  let outputBlock = section.querySelector(".output-block");
  if (outputBlock) outputBlock.remove();
  outputBlock = document.createElement("div");
  outputBlock.className = "output-block";
  outputBlock.innerHTML =
    '<div class="output-bar">' +
      '<span class="label">▸ ' + escapeHtml(built.label) + ' · ' + escapeHtml(s.nome) + '</span>' +
      '<div class="actions-mini">' +
        '<button onclick="copyOutput(this)">Copiar</button>' +
        '<button onclick="downloadOutput(this)">↓ MD</button>' +
      '</div>' +
    '</div>' +
    '<div class="output-content"><div class="streaming-indicator"><span class="pulse"></span>Aguardando API...</div></div>';
  section.querySelector(".card").appendChild(outputBlock);
  outputBlock.scrollIntoView({behavior:"smooth", block:"center"});

  const startTime = Date.now();
  try {
    const payload = {
      model: apiConfig.model,
      max_tokens: apiConfig.maxTokens,
      messages: [{role:"user", content: built.prompt}]
    };
    if (apiConfig.webSearch) payload.tools = [{type:"web_search_20250305", name:"web_search"}];
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method:"POST",
      headers:{ "Content-Type":"application/json","x-api-key":apiConfig.key,
        "anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},
      body:JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message || "Erro API");
    const text = (data.content || []).filter(b => b.type === "text").map(b => b.text).join("\n\n");
    const elapsed = ((Date.now() - startTime)/1000).toFixed(1);
    const usage = data.usage || {};
    const cost = calculateCost(usage, apiConfig.model);

    // Parse ADD_TO_DB
    const {cleanText, suggestions} = parseAddToDb(text);

    state.history.push({
      ts: Date.now(), shoppingId: s.id, shoppingNome: s.nome,
      type: built.type, sectionId, label: built.label,
      prompt: built.prompt, output: text, usage, cost, elapsed,
      model: apiConfig.model, webSearchUsed: apiConfig.webSearch,
      suggestions
    });
    if (state.history.length > 50) state.history = state.history.slice(-50);
    await saveState();

    // Render output: cleanText + suggestions
    const contentDiv = outputBlock.querySelector(".output-content");
    let outputHtml = renderMarkdown(cleanText);
    if (suggestions.length > 0) {
      outputHtml += renderSuggestions(suggestions);
    }
    contentDiv.innerHTML = outputHtml;

    const stats = document.createElement("div");
    stats.className = "stats-bar";
    stats.innerHTML =
      '<span class="stat">Modelo: <span class="v">'+apiConfig.model.split("-").slice(1,3).join(" ")+'</span></span>' +
      '<span class="stat">Tokens in: <span class="v">'+(usage.input_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tokens out: <span class="v">'+(usage.output_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tempo: <span class="v">'+elapsed+'s</span></span>' +
      '<span class="stat">Custo: <span class="v">$'+cost.toFixed(3)+'</span></span>' +
      (suggestions.length > 0 ? '<span class="stat">Sugestões: <span class="v" style="color:var(--moss);">'+suggestions.length+'</span></span>' : '');
    outputBlock.appendChild(stats);
    toast("✓ Concluído em " + elapsed + "s" + (suggestions.length>0 ? " · "+suggestions.length+" sugestões" : ""), "success");
    renderHome();
  } catch(e) {
    outputBlock.querySelector(".output-content").innerHTML =
      '<div style="color:var(--accent);padding:20px;"><strong>Erro:</strong> ' + escapeHtml(e.message) + '</div>';
    toast("Erro: " + e.message, "error");
  } finally {
    btn.disabled = false;
    btn.innerHTML = origText;
  }
}

function calculateCost(usage, model) {
  const p = PRICING[model] || PRICING["claude-sonnet-4-6-20250929"];
  return (usage.input_tokens || 0) / 1e6 * p.input + (usage.output_tokens || 0) / 1e6 * p.output;
}

// =================== AUTO-CADASTRO PARSER ===================
function parseAddToDb(text) {
  // Procura blocos: ```ADD_TO_DB:<dbKey>\n<JSON>\n```
  // Ou variações: ```add_to_db:..., ADD_TO_DB:..., etc.
  const suggestions = [];
  const regex = /```\s*ADD_TO_DB\s*:\s*([a-z_]+)\s*\n([\s\S]*?)```/gi;
  let cleanText = text;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const dbKey = match[1].toLowerCase().trim();
    const jsonRaw = match[2].trim();
    if (!DATABASES[dbKey]) continue;
    try {
      const parsed = JSON.parse(jsonRaw);
      suggestions.push({
        id: "sug_" + Date.now().toString(36) + "_" + suggestions.length + Math.random().toString(36).substr(2,3),
        dbKey,
        data: parsed,
        added: false
      });
    } catch(e) {
      // Tenta aceitar JSON com aspas simples ou trailing comma comum em LLM output
      try {
        const fixed = jsonRaw.replace(/'/g, '"').replace(/,(\s*[}\]])/g, "$1");
        const parsed = JSON.parse(fixed);
        suggestions.push({
          id: "sug_" + Date.now().toString(36) + "_" + suggestions.length,
          dbKey, data: parsed, added: false
        });
      } catch(e2) {
        console.warn("JSON inválido em ADD_TO_DB:", jsonRaw, e2.message);
      }
    }
  }
  // Remove os blocos do texto
  cleanText = text.replace(regex, "").trim();
  return {cleanText, suggestions};
}

function renderSuggestions(suggestions) {
  let html = '<div class="add-suggestions">';
  html += '<div class="title">Auto-cadastro · '+suggestions.length+' sugestão(ões) detectada(s)</div>';
  suggestions.forEach(sug => {
    const db = DATABASES[sug.dbKey];
    const dbName = db ? db.title : sug.dbKey;
    const labelF = db ? db.label_field : null;
    const previewName = labelF && sug.data[labelF] ? sug.data[labelF] : Object.values(sug.data)[0] || "(sem nome)";
    const previewFields = Object.entries(sug.data).slice(0, 4).map(([k,v]) => k+": "+(Array.isArray(v)?v.join("/"):v)).join(" · ");
    html += '<div class="add-suggestion-card" id="sug-card-'+sug.id+'">';
    html += '<div class="info">';
    html += '<div class="target">→ '+escapeHtml(dbName)+'</div>';
    html += '<div><strong>'+escapeHtml(String(previewName))+'</strong></div>';
    html += '<div class="preview">'+escapeHtml(previewFields)+'</div>';
    html += '</div>';
    html += '<div style="display:flex;gap:5px;">';
    html += '<button class="btn" onclick="reviewSuggestion(\''+sug.id+'\')">Revisar</button>';
    html += '<button class="btn btn-success" onclick="addSuggestion(\''+sug.id+'\')">+ Adicionar</button>';
    html += '</div></div>';
  });
  html += '<div style="margin-top:10px;text-align:right;">';
  html += '<button class="btn btn-success" onclick="addAllSuggestions(\''+suggestions[0].id.split("_").slice(0,-1).join("_")+'\')">+ Adicionar todas</button>';
  html += '</div>';
  html += '</div>';
  // Salva referência global para handlers
  window._currentSuggestions = (window._currentSuggestions || []).concat(suggestions);
  return html;
}

function findSuggestion(sugId) {
  return (window._currentSuggestions || []).find(s => s.id === sugId);
}

async function addSuggestion(sugId) {
  const sug = findSuggestion(sugId);
  if (!sug || sug.added) return;
  const db = DATABASES[sug.dbKey];
  if (!db) { toast("Base não encontrada: "+sug.dbKey, "error"); return; }
  // Para bases shopping-scoped, precisa de shopping ativo
  if (db.scope === "shopping" && !state.activeShoppingId) {
    toast("Selecione um shopping primeiro", "error"); return;
  }
  const record = {...sug.data};
  if (!record.id) record.id = "rec_" + Date.now().toString(36) + Math.random().toString(36).substr(2,5);
  const records = getDbRecords(sug.dbKey);
  records.push(record);
  saveDbRecords(sug.dbKey, records);
  await saveState();
  sug.added = true;
  const card = document.getElementById("sug-card-"+sugId);
  if (card) {
    card.classList.add("added");
    const btn = card.querySelector(".btn-success");
    if (btn) { btn.textContent = "✓ Adicionado"; btn.disabled = true; }
  }
  renderDbsNav();
  toast("Adicionado à base "+db.title, "success");
}

function reviewSuggestion(sugId) {
  const sug = findSuggestion(sugId);
  if (!sug) return;
  // Abre modal pré-preenchido para revisão antes de salvar
  openRecordModal(sug.dbKey, sug.data);
  // Marca como "added" depois que usuário salvar via modal? Por simplicidade, mantém.
}

async function addAllSuggestions(_prefix) {
  if (!window._currentSuggestions) return;
  let added = 0;
  for (const sug of window._currentSuggestions) {
    if (sug.added) continue;
    await addSuggestion(sug.id);
    added++;
  }
  toast("✓ "+added+" registros adicionados", "success");
}

// =================== MARKDOWN ===================
function renderMarkdown(text) {
  if (!text) return "";
  let h = escapeHtml(text);
  h = h.replace(/^### (.+)$/gm, '<h3>$1</h3>')
       .replace(/^## (.+)$/gm, '<h2>$1</h2>')
       .replace(/^# (.+)$/gm, '<h1>$1</h1>')
       .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
       .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
       .replace(/(^|[^*])\*([^*\n]+)\*([^*]|$)/g, '$1<em>$2</em>$3')
       .replace(/`([^`]+)`/g, '<code>$1</code>');
  h = h.replace(/(\|.+\|\n\|[\s\-:|]+\|\n(?:\|.+\|\n?)+)/g, m => {
    const lines = m.trim().split("\n");
    const head = lines[0].split("|").slice(1,-1).map(c => '<th>'+c.trim()+'</th>').join("");
    const rows = lines.slice(2).map(l => '<tr>' + l.split("|").slice(1,-1).map(c => '<td>'+c.trim()+'</td>').join("") + '</tr>').join("");
    return '<table><thead><tr>'+head+'</tr></thead><tbody>'+rows+'</tbody></table>';
  });
  h = h.replace(/^(\s*)([-*+]) (.+)$/gm, '$1<li>$3</li>')
       .replace(/(<li>.*<\/li>\n?)+/g, m => '<ul>'+m+'</ul>')
       .replace(/^(\s*)\d+\. (.+)$/gm, '$1<oli>$2</oli>')
       .replace(/(<oli>.*<\/oli>\n?)+/g, m => '<ol>'+m.replace(/oli/g,"li")+'</ol>');
  h = h.split(/\n\n+/).map(p => {
    if (p.match(/^<(h\d|ul|ol|table|li)/)) return p;
    return '<p>'+p.replace(/\n/g,"<br>")+'</p>';
  }).join("\n");
  return h;
}

