  .add-suggestion-card { background:white; border:1px solid var(--rule-soft); border-radius:5px; padding:11px 13px; margin-bottom:8px; display:flex; justify-content:space-between; align-items:center; gap:10px; }
  .add-suggestion-card:last-child { margin-bottom:0; }
  .add-suggestion-card .info { flex:1; font-size:12px; }
  .add-suggestion-card .target { font-family:var(--mono); font-size:10px; color:var(--accent); font-weight:700; margin-bottom:3px; }
  .add-suggestion-card .preview { color:var(--steel); }
  .add-suggestion-card button { padding:6px 12px; font-size:11px; }
  .add-suggestion-card.added { opacity:0.5; }
  .add-suggestion-card.added button { background:var(--moss); color:white; border-color:var(--moss); cursor:default; }

  .streaming-indicator { display:inline-flex; align-items:center; gap:6px; color:var(--accent); font-family:var(--mono); font-size:11px; }
  .streaming-indicator .pulse { width:7px; height:7px; background:var(--accent); border-radius:50%; animation:pulse 1.4s infinite; }
  @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }

  .cost-estimate { background:var(--paper-soft); border-left:3px solid var(--gold); padding:9px 13px; border-radius:0 4px 4px 0; font-size:11.5px; margin-top:11px; font-family:var(--mono); color:var(--ink-soft); }

  .stats-bar { display:flex; gap:14px; padding:9px 16px; background:var(--paper-soft); border-top:1px solid var(--rule-soft); font-family:var(--mono); font-size:10.5px; color:var(--steel); flex-wrap:wrap; }
  .stats-bar .stat .v { color:var(--ink); font-weight:700; }

  /* HOME hero */
  .hero { background:var(--ink); color:var(--paper); border-radius:10px; padding:34px 30px; position:relative; overflow:hidden; margin-bottom:24px; }
  .hero::before { content:""; position:absolute; top:-40px; right:-40px; width:240px; height:240px; background:radial-gradient(circle,var(--accent) 0%,transparent 70%); opacity:0.28; }
  .hero h1 { font-family:var(--display); font-weight:900; font-size:38px; line-height:0.95; letter-spacing:-0.03em; margin-bottom:12px; position:relative; max-width:680px; }
  .hero h1 em { font-style:italic; font-weight:500; color:var(--accent-2); }
  .hero p { font-size:14px; color:var(--paper-soft); max-width:580px; line-height:1.55; position:relative; }
  .hero .meta-row { display:flex; gap:24px; margin-top:18px; font-family:var(--mono); font-size:11px; color:var(--paper-soft); position:relative; }
  .hero .meta-row .v { color:var(--accent-2); font-weight:700; }

  /* Categoria headers no Home */
  .cat-section { margin-bottom:30px; }
  .cat-section .cat-header { display:flex; align-items:center; gap:10px; margin-bottom:10px; padding-bottom:7px; border-bottom:1px solid var(--rule-soft); }
  .cat-section .cat-header .cat-mark { width:28px; height:28px; border-radius:6px; display:flex; align-items:center; justify-content:center; font-family:var(--display); font-size:14px; color:white; }
  .cat-section .cat-header h2 { font-family:var(--display); font-size:22px; font-weight:700; letter-spacing:-0.01em; }
  .cat-section .cat-header .count { margin-left:auto; font-family:var(--mono); font-size:11px; color:var(--steel); }

  .grid-3 { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; }
  .grid-4 { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; }

  .item-card { background:white; border:1px solid var(--rule-soft); border-radius:6px; padding:14px 16px; cursor:pointer; transition:all 0.18s; position:relative; }
  .item-card:hover { border-color:var(--ink); transform:translateY(-1px); box-shadow:0 6px 16px -4px rgba(13,17,23,0.12); }
  .item-card .ic-num { font-family:var(--mono); font-size:9px; color:var(--gold); letter-spacing:0.08em; }
  .item-card h4 { font-family:var(--display); font-weight:700; font-size:15px; line-height:1.2; margin:4px 0 5px; letter-spacing:-0.01em; }
  .item-card p { font-size:11.5px; color:var(--steel); line-height:1.45; }

  .item-card.wf .ic-num { color:var(--accent-2); }
  .item-card.db .ic-num { color:var(--moss); }
  .item-card.db .db-icon { font-family:var(--display); font-size:22px; color:var(--moss); line-height:1; margin-bottom:4px; }
  .item-card.db .db-stats { margin-top:8px; font-family:var(--mono); font-size:10px; color:var(--steel); display:flex; gap:8px; }
  .item-card.db .db-stats .v { color:var(--accent); font-weight:700; }

  /* MODAL */
  .modal-bg { display:none; position:fixed; inset:0; background:rgba(13,17,23,0.7); z-index:200; justify-content:center; align-items:center; backdrop-filter:blur(4px); padding:20px; }
  .modal-bg.active { display:flex; }
  .modal { background:var(--paper); border-radius:10px; padding:26px; width:100%; max-width:640px; box-shadow:0 20px 60px rgba(0,0,0,0.4); max-height:90vh; overflow-y:auto; }
  .modal.wide { max-width:900px; }
  .modal h2 { font-family:var(--display); font-size:22px; font-weight:700; margin-bottom:5px; letter-spacing:-0.01em; }
  .modal .desc { color:var(--steel); font-size:13px; margin-bottom:18px; }

  .toast { position:fixed; bottom:24px; right:24px; background:var(--ink); color:var(--paper); padding:11px 18px; border-radius:5px; font-size:12.5px; opacity:0; transform:translateY(20px); transition:all 0.25s; z-index:300; box-shadow:0 12px 32px rgba(0,0,0,0.25); border-left:3px solid var(--accent); font-family:var(--mono); letter-spacing:0.02em; }
  .toast.show { opacity:1; transform:translateY(0); }
  .toast.error { background:#4a1a14; }
  .toast.success { border-left-color:var(--moss); }

  .banner { background:var(--paper-soft); border-left:3px solid var(--gold); padding:11px 15px; border-radius:0 5px 5px 0; font-size:12.5px; margin-bottom:16px; }
  .banner.warn { border-left-color:var(--accent); background:#fdf0ec; }
  .banner.info { border-left-color:var(--moss); }
  .banner strong { color:var(--accent); }

  .section { display:none; animation:fadeIn 0.25s; }
  .section.active { display:block; }
  @keyframes fadeIn { from { opacity:0; transform:translateY(6px); } to { opacity:1; transform:translateY(0); } }

  .help-text { font-size:11px; color:var(--steel); margin-top:5px; font-family:var(--mono); line-height:1.5; }
  .help-text a { color:var(--accent); }

  .injection-info { background:var(--paper-soft); border:1px dashed var(--moss); border-radius:5px; padding:10px 14px; margin:8px 0 14px; font-size:11.5px; }
  .injection-info .title { font-family:var(--mono); font-size:9.5px; letter-spacing:0.12em; text-transform:uppercase; color:var(--moss); font-weight:700; margin-bottom:5px; }
  .injection-info .list { display:flex; flex-wrap:wrap; gap:5px; }
  .injection-info .chip { background:white; padding:3px 8px; border-radius:7px; font-size:10.5px; border:1px solid var(--rule-soft); }
  .injection-info .chip .n { color:var(--accent); font-weight:700; }

  @media (max-width:1024px) {
    .app { grid-template-columns:1fr; }
    .sidebar { position:relative; height:auto; }
    main { padding:20px; }
    .grid-3,.grid-4 { grid-template-columns:1fr; }
    .form-grid { grid-template-columns:1fr; }
    h1.page-title { font-size:28px; }
  }
</style>
</head>
<body>

<div class="app">

<aside class="sidebar">
  <div class="brand">
    <div class="mark">Shopping<span class="dot">.</span>OS</div>
    <div class="sub">v3 · Console</div>
  </div>

  <div class="api-status" id="apiStatusBox" onclick="openApiModal()">
    <span class="dot-led" id="apiLed"></span>
    <span class="label" id="apiStatusLabel">API não configurada</span>
    <span style="color:var(--steel);">⚙</span>
  </div>

  <div class="shopping-switcher">
    <div class="label">Shopping ativo</div>
    <select id="shoppingSelect" onchange="changeShopping(this.value)"></select>
    <div class="meta" id="shoppingMeta"></div>
    <button class="new" onclick="openShoppingModal()">+ Novo shopping</button>
  </div>

  <nav>
    <div class="nav-group">
      <div class="group-label">Início</div>
      <div class="nav-item active" data-section="home" onclick="navigate('home')"><span class="num">⌂</span><span>Console</span></div>
      <div class="nav-item" data-section="shopping" onclick="navigate('shopping')"><span class="num">⊕</span><span>Perfil</span></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Bases de Dados</div>
      <div id="dbsNav"></div>
    </div>

    <div class="nav-group">
      <div class="group-label">Workflows</div>
      <div class="nav-item workflow" data-section="wf1" onclick="navigate('wf1')"><span class="num">W1</span><span>Vacancy-to-Contract</span></div>
      <div class="nav-item workflow" data-section="wf2" onclick="navigate('wf2')"><span class="num">W2</span><span>Street-to-Shopping</span></div>
      <div class="nav-item workflow" data-section="wf3" onclick="navigate('wf3')"><span class="num">W3</span><span>Cluster Experience</span></div>
    </div>

    <div class="nav-group" id="agentsByCategory"></div>

    <div class="nav-group">
      <div class="group-label">Sistema</div>
      <div class="nav-item" data-section="history" onclick="navigate('history')"><span class="num">⌖</span><span>Histórico</span></div>
      <div class="nav-item" data-section="data" onclick="navigate('data')"><span class="num">⇄</span><span>Import / Export</span></div>
    </div>
  </nav>
</aside>


<main>

<!-- HOME -->
<section id="home" class="section active">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Console</span></div>

  <div class="hero">
    <h1>Onde<br>oportunidade <em>vira contrato.</em></h1>
    <p>Sistema completo de gestão comercial multi-shopping. 7 bases de dados alimentam 16 agentes especializados que retornam análises acionáveis via API.</p>
    <div class="meta-row">
      <span>Execuções: <span class="v" id="cntExecutions">0</span></span>
      <span>Tokens: <span class="v" id="cntTokens">0</span></span>
      <span>Custo: <span class="v" id="cntCost">$0.00</span></span>
    </div>
  </div>

  <div id="apiWarning" class="banner warn" style="display:none;">
    <strong>API não configurada.</strong> Configure sua chave Anthropic no canto superior esquerdo.
  </div>

  <!-- BASES -->
  <div class="cat-section">
    <div class="cat-header">
      <div class="cat-mark" style="background:var(--moss);">▤</div>
      <h2>Bases de Dados</h2>
      <span class="count">7 bases estruturadas</span>
    </div>
    <div class="grid-4" id="homeDbsGrid"></div>
  </div>

  <!-- WORKFLOWS -->
  <div class="cat-section">
    <div class="cat-header">
      <div class="cat-mark" style="background:var(--accent-2);">◐</div>
      <h2>Workflows</h2>
      <span class="count">3 sprints orquestrados</span>
    </div>
    <div class="grid-3">
      <div class="item-card wf" onclick="navigate('wf1')"><div class="ic-num">WORKFLOW 01</div><h4>Vacancy-to-Contract Sprint</h4><p>Reduz vacância e encurta ciclo vaga → contrato.</p></div>
      <div class="item-card wf" onclick="navigate('wf2')"><div class="ic-num">WORKFLOW 02</div><h4>Street-to-Shopping</h4><p>Converte operadores de rua em lojistas.</p></div>
      <div class="item-card wf" onclick="navigate('wf3')"><div class="ic-num">WORKFLOW 03</div><h4>Cluster Experience Growth</h4><p>Frequência, ticket e experiência.</p></div>
    </div>
  </div>

  <!-- AGENTES POR CATEGORIA -->
  <div id="homeAgentsByCategory"></div>
</section>


<!-- PERFIL DO SHOPPING -->
<section id="shopping" class="section">
  <div class="breadcrumb">CADASTRO <span class="sep">/</span> <span class="current">Perfil</span></div>
  <h1 class="page-title">Perfil do Shopping</h1>
  <p class="page-desc">Define o contexto que <strong>todos os agentes e bases</strong> usam.</p>

  <div class="card">
    <h2>Identificação</h2>
    <div class="form-grid">
      <div class="full"><label>Nome <span class="required">*</span></label><input type="text" id="sh_nome"></div>
      <div><label>Cidade <span class="required">*</span></label><input type="text" id="sh_cidade"></div>
      <div><label>Estado</label><input type="text" id="sh_estado"></div>
      <div class="full"><label>Endereço</label><input type="text" id="sh_endereco"></div>
      <div>
        <label>Cluster <span class="required">*</span></label>
        <select id="sh_cluster">
          <option value="">— selecione —</option>
          <option>Sofisticados</option><option>Compactos de Alto Padrão</option>
          <option>Entretenimento</option><option>Passeio Familiar</option>
          <option>Imensos</option><option>Convenientes</option>
        </select>
      </div>
      <div><label>Operador</label><input type="text" id="sh_operador"></div>
    </div>
  </div>

  <div class="card">
    <h2>Métricas físicas</h2>
    <div class="form-grid">
      <div><label>ABL total (m²)</label><input type="number" id="sh_abl"></div>
      <div><label>Total de lojas</label><input type="number" id="sh_lojas"></div>
      <div><label>Inauguração</label><input type="number" id="sh_ano"></div>
      <div><label>Última reforma</label><input type="number" id="sh_reforma"></div>
      <div><label>Vacância (%)</label><input type="number" id="sh_vacancia" min="0" max="100"></div>
      <div><label>ABL vaga (m²)</label><input type="number" id="sh_abl_vaga"></div>
    </div>
  </div>

  <div class="card">
    <h2>Posicionamento e diagnóstico</h2>
    <div class="form-grid">
      <div class="full">
        <label>Batalhas prioritárias <span class="hint">selecione 2-4</span></label>
        <div class="pill-group" id="sh_batalhas_group">
          <label class="pill-check"><input type="checkbox" value="Lojas"><span>Lojas</span></label>
          <label class="pill-check"><input type="checkbox" value="Gastronomia"><span>Gastronomia</span></label>
          <label class="pill-check"><input type="checkbox" value="Entretenimento"><span>Entretenimento</span></label>
          <label class="pill-check"><input type="checkbox" value="Hospitality"><span>Hospitality</span></label>
          <label class="pill-check"><input type="checkbox" value="Serviços"><span>Serviços</span></label>
          <label class="pill-check"><input type="checkbox" value="Ambiência"><span>Ambiência</span></label>
          <label class="pill-check"><input type="checkbox" value="Entorno"><span>Entorno</span></label>
          <label class="pill-check"><input type="checkbox" value="Jornada sem fricção"><span>Jornada sem fricção</span></label>
        </div>
      </div>
      <div class="full"><label>Target principal</label><textarea id="sh_target"></textarea></div>
      <div class="full"><label>Concorrência direta</label><textarea id="sh_concorrencia"></textarea></div>
      <div class="full"><label>Pontos fortes</label><textarea id="sh_fortes"></textarea></div>
      <div class="full"><label>Lacunas de mix</label><textarea id="sh_lacunas"></textarea></div>
      <div class="full"><label>Lojas em saída/risco</label><textarea id="sh_saidas"></textarea></div>
      <div class="full"><label>Mix atual <span class="hint">filtro duplicidade</span></label><textarea id="sh_mix"></textarea></div>
    </div>
    <div class="actions">
      <button class="btn btn-primary" onclick="saveShopping()">Salvar</button>
      <button class="btn btn-danger" onclick="confirmDeleteShopping()">Excluir shopping</button>
      <span style="margin-left:auto;color:var(--steel);font-size:12px;" id="shoppingSaveStatus"></span>
    </div>
  </div>
</section>

<div id="dynamicSections"></div>


<!-- HISTÓRICO -->
<section id="history" class="section">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Histórico</span></div>
  <h1 class="page-title">Histórico</h1>
  <p class="page-desc">Últimas 50 execuções de todos os shoppings.</p>
  <div class="card" style="padding:0;">
    <div id="historyList" style="max-height:680px;overflow-y:auto;"></div>
  </div>
</section>


<!-- IMPORT / EXPORT -->
<section id="data" class="section">
  <div class="breadcrumb">SISTEMA <span class="sep">/</span> <span class="current">Import / Export</span></div>
  <h1 class="page-title">Import / Export</h1>
  <p class="page-desc">Backup, restauração e portabilidade dos dados.</p>

  <div class="card">
    <h2>Backup completo</h2>
    <p class="card-desc">Todos os shoppings + todas as bases + histórico em um único arquivo JSON. Use para migrar ou compartilhar com o time.</p>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn btn-primary" onclick="exportAll()">↓ Exportar tudo (JSON)</button>
      <button class="btn btn-success" onclick="importAll()">↑ Importar JSON completo</button>
    </div>
  </div>

  <div class="card">
    <h2>Por shopping</h2>
    <p class="card-desc">Exporta o shopping ativo com suas bases e histórico — útil para enviar análise específica.</p>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn" onclick="exportCurrentShopping()">↓ Exportar shopping ativo</button>
      <button class="btn" onclick="importShopping()">↑ Importar shopping</button>
    </div>
  </div>

  <div class="card">
    <h2>Por base de dados</h2>
    <p class="card-desc">Exporta/importa uma base individual em JSON ou CSV. CSV facilita edição em Excel.</p>
    <div style="display:grid;grid-template-columns:1fr auto auto auto auto;gap:8px;align-items:end;">
      <div>
        <label>Base</label>
        <select id="dbExportSelect"></select>
      </div>
      <button class="btn" onclick="exportSingleDB('json')">↓ JSON</button>
      <button class="btn" onclick="exportSingleDB('csv')">↓ CSV</button>
      <button class="btn btn-success" onclick="importSingleDB('json')">↑ JSON</button>
      <button class="btn btn-success" onclick="importSingleDB('csv')">↑ CSV</button>
    </div>
    <p class="help-text" style="margin-top:10px;">CSV: campos múltiplos separados por "/" (ex: "Moda/Beleza"). Para escopo global (Marcas/Fornecedores/Produtos), aplica a todo o sistema. Para escopo por shopping, aplica ao shopping ativo.</p>
  </div>

  <div class="card">
    <h2 style="color:var(--accent);">Zona de risco</h2>
    <p class="card-desc">Apagar todos os dados — não tem volta.</p>
    <div class="actions" style="margin-top:0;padding-top:0;border:none;">
      <button class="btn btn-danger" onclick="clearAllData()">Apagar tudo</button>
    </div>
  </div>
</section>

</main>
</div>


<!-- MODALS -->
<div class="modal-bg" id="modalApi">
  <div class="modal">
    <h2>Configurar API Anthropic</h2>
    <p class="desc">Cole sua chave. Fica salva apenas no seu navegador.</p>
    <div class="banner warn"><strong>Segurança:</strong> não use em máquinas compartilhadas.</div>
    <div style="display:grid;gap:13px;">
      <div>
        <label>Chave de API <span class="required">*</span></label>
        <input type="password" id="apiKeyInput" placeholder="sk-ant-...">
        <div class="help-text">Crie em <a href="https://console.anthropic.com/settings/keys" target="_blank">console.anthropic.com/settings/keys</a></div>
      </div>
      <div>
        <label>Modelo</label>
        <select id="apiModel">
          <option value="claude-sonnet-4-6-20250929" selected>Sonnet 4.6 (recomendado)</option>
          <option value="claude-opus-4-7-20251201">Opus 4.7 (mais caro)</option>
          <option value="claude-haiku-4-5-20251001">Haiku 4.5 (rápido/barato)</option>
        </select>
      </div>
      <div>
        <label>Web Search <span class="hint">+$0.01/call</span></label>
        <select id="apiWebSearch">
          <option value="true" selected>Habilitado</option>
          <option value="false">Desabilitado</option>
        </select>
      </div>
      <div>
        <label>Max tokens da resposta</label>
        <input type="number" id="apiMaxTokens" value="6000" min="1000" max="16000">
        <div class="help-text">Padrão otimizado: 6000. Workflows complexos: 8000+.</div>
      </div>
    </div>
    <div class="actions" style="margin-top:20px;padding-top:14px;">
      <button class="btn btn-primary" onclick="saveApiConfig()">Salvar e testar</button>
      <button class="btn btn-danger" onclick="clearApiKey()">Remover</button>
      <button class="btn btn-ghost" onclick="closeApiModal()">Cancelar</button>
    </div>
  </div>
</div>

<div class="modal-bg" id="modalShopping">
  <div class="modal">
    <h2>Novo shopping</h2>
    <div style="display:grid;gap:12px;">
      <div><label>Nome <span class="required">*</span></label><input type="text" id="newSh_nome"></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <div><label>Cidade <span class="required">*</span></label><input type="text" id="newSh_cidade"></div>
        <div><label>Estado</label><input type="text" id="newSh_estado"></div>
      </div>
      <div>
        <label>Cluster <span class="required">*</span></label>
        <select id="newSh_cluster">
          <option value="">—</option><option>Sofisticados</option><option>Compactos de Alto Padrão</option>
          <option>Entretenimento</option><option>Passeio Familiar</option>
          <option>Imensos</option><option>Convenientes</option>
        </select>
      </div>
    </div>
    <div class="actions" style="margin-top:20px;padding-top:14px;">
      <button class="btn btn-primary" onclick="createShopping()">Criar</button>
      <button class="btn btn-ghost" onclick="closeShoppingModal()">Cancelar</button>
    </div>
  </div>
</div>

<div class="modal-bg" id="modalRecord">
  <div class="modal wide">
    <h2 id="recordModalTitle">Novo registro</h2>
    <p class="desc" id="recordModalDesc"></p>
    <div id="recordModalForm"></div>
    <div class="actions" style="margin-top:20px;padding-top:14px;">
      <button class="btn btn-primary" onclick="saveRecord()">Salvar</button>
      <button class="btn btn-danger" id="deleteRecordBtn" style="display:none;" onclick="deleteCurrentRecord()">Excluir</button>
      <button class="btn btn-ghost" onclick="closeRecordModal()">Cancelar</button>
    </div>
  </div>
</div>

<div class="toast" id="toast"></div>

<script>
// =================== INJETADOS ===================
const DATABASES = __DATABASES_JSON__;
const AGENTS = __AGENTS_JSON__;
const CATEGORIES_META = __CATEGORIES_JSON__;

const PRICING = {
  "claude-sonnet-4-6-20250929": {input:3.00, output:15.00},
  "claude-opus-4-7-20251201":   {input:15.00, output:75.00},
  "claude-haiku-4-5-20251001":  {input:1.00, output:5.00}
};

// =================== ESTADO ===================
let state = {
  shoppings:{}, activeShoppingId:null,
  history:[], drafts:{}, dbs:{}, globalDbs:{}
};
let apiConfig = { key:"", model:"claude-sonnet-4-6-20250929", webSearch:true, maxTokens:6000 };
let currentRecordEdit = null;

// =================== STORAGE ===================
async function loadState() {
  try {
    const r = await window.storage.get("sios-state-v3");
    if (r && r.value) state = JSON.parse(r.value);
  } catch(e) {}
  if (!state.shoppings) state.shoppings = {};
  if (!state.dbs) state.dbs = {};
  if (!state.globalDbs) state.globalDbs = {};
  if (!state.history) state.history = [];
  if (!state.drafts) state.drafts = {};
  Object.keys(DATABASES).forEach(k => {
    if (DATABASES[k].scope === "global" && !state.globalDbs[k]) state.globalDbs[k] = [];
  });
  if (Object.keys(state.shoppings).length === 0) {
    seedPlaza();
    await saveState();
  }
  if (state.activeShoppingId && !state.dbs[state.activeShoppingId]) {
    state.dbs[state.activeShoppingId] = {};
    Object.keys(DATABASES).forEach(k => {
      if (DATABASES[k].scope === "shopping") state.dbs[state.activeShoppingId][k] = [];
    });
  }
  try {
    const a = localStorage.getItem("sios-api-config");
    if (a) apiConfig = {...apiConfig, ...JSON.parse(a)};
  } catch(e) {}
}

async function saveState() {
  try { await window.storage.set("sios-state-v3", JSON.stringify(state)); } catch(e) {}
}
function saveApiConfigToStorage() {
  try { localStorage.setItem("sios-api-config", JSON.stringify(apiConfig)); } catch(e) {}
}

function seedPlaza() {
  const id = "plaza-niteroi-" + Date.now();
  state.shoppings[id] = {
    id, nome:"Plaza Shopping Niterói", cidade:"Niterói", estado:"RJ",
    endereco:"Rua XV de Novembro, 8, Centro", cluster:"Entretenimento",
    operador:"Allos", abl:43000, lojas:300, ano:1986, abl_vaga:6028,
    batalhas:["Entretenimento","Gastronomia","Lojas"],
    target:"Famílias do Centro de Niterói + público regional.",
    concorrencia:"Bay Market, Icaraí Shopping, Niterói Shopping. Polos: Gavião Peixoto, Conde de Bonfim.",
    fortes:"Cinemark mantido, Espaço Gourmet consolidado.",
    lacunas:"Entret adulto, gastronomia autoral, cafés especiais.",
    saidas:"39 saídas Ano 1 (~6.028m²) + foyer Cinemark redev (5.097m²).",
    mix:"Cinemark, Coco Bambu, Outback, Madero, Abbraccio, NOI, L'Entrecôte, Benihana, Renner, Riachuelo, C&A, Marisa, Forever 21, Calvin Klein, Lacoste, GAP, Levi's, Reserva, Decathlon, Nike, Centauro, Trackfield, LEGO, Ri Happy, Bacio di Latte, Oakberry, Yogoberry, Bibi Sucos, Habib's"
  };
  state.activeShoppingId = id;
  state.dbs[id] = {};
  Object.keys(DATABASES).forEach(k => {
    if (DATABASES[k].scope === "shopping") state.dbs[id][k] = [];
  });
  state.dbs[id].hunter_targets = [
    {id:"h1", nome:"Bullguer", categoria:"Alimentação", subcategoria:"Hambúrguer autoral", cidade:"Rio de Janeiro", bairro:"Ipanema", raio_km:15, presenca_shopping:"AUSENTE", status_abordagem:"Identificado", score_fit:90, notas:"Várias unidades ZS Rio"},
    {id:"h2", nome:"Ferro e Farinha", categoria:"Alimentação", subcategoria:"Pizza autoral", cidade:"Rio de Janeiro", bairro:"Catete", raio_km:14, presenca_shopping:"AUSENTE", status_abordagem:"Identificado", score_fit:90, notas:"4 unidades RJ"},
    {id:"h3", nome:"Tenore Churrascaria", categoria:"Alimentação", subcategoria:"Churrascaria", cidade:"Niterói", bairro:"Icaraí", raio_km:3, presenca_shopping:"AUSENTE", status_abordagem:"Identificado", score_fit:78, notas:"Vista praia Icaraí"}
  ];
  if (!state.globalDbs.marcas || state.globalDbs.marcas.length === 0) {
    state.globalDbs.marcas = [
      {id:"m1", nome_marca:"H&M Brasil", categoria:"Moda", subcategoria:"Fast fashion internacional", modelo_exp:"Loja própria", unidades_ativas:8, contato_nome:"Grupo Dorben (JV)", status_ka:"Watchlist", notas:"Plano expansão RJ 2026"},
      {id:"m2", nome_marca:"Bossa Nova Bowl", categoria:"Entretenimento", subcategoria:"Boliche compacto", site:"bossanovabowl.com.br", status_ka:"Watchlist"},
      {id:"m3", nome_marca:"Cobasi", categoria:"Pet", subcategoria:"Pet shop full", modelo_exp:"Loja própria", site:"cobasi.com.br", status_ka:"Watchlist"}
    ];
  }
  if (!state.globalDbs.produtos_fin || state.globalDbs.produtos_fin.length === 0) {
    state.globalDbs.produtos_fin = [
      {id:"f1", nome_produto:"Crédito para obra Allos", tipo:"Crédito para obra", parceiro:"Itaú BBA", valor_min:50000, valor_max:500000, taxa_juros:1.5, status_produto:"Ativo"}
    ];
  }
}

// =================== NAV ===================
function navigate(sectionId) {
  document.querySelectorAll(".section").forEach(s => s.classList.remove("active"));
  const sect = document.getElementById(sectionId);
  if (sect) sect.classList.add("active");
  document.querySelectorAll(".nav-item").forEach(n => n.classList.remove("active"));
  const nav = document.querySelector('.nav-item[data-section="'+sectionId+'"]');
  if (nav) nav.classList.add("active");
  window.scrollTo({top:0, behavior:"smooth"});
  if (sectionId === "home") renderHome();
  if (sectionId === "shopping") loadShoppingProfile();
  if (sectionId === "history") renderHistory();
  if (sectionId === "data") populateDbExportSelect();
  if (sectionId.startsWith("db-")) renderDbList(sectionId.replace("db-",""));
  if (sectionId.startsWith("wf") || sectionId.startsWith("agent-")) {
    loadDraft(sectionId);
    renderInjectionInfo(sectionId);
  }
}

// =================== SHOPPING SWITCH ===================
function renderShoppingSwitcher() {
  const sel = document.getElementById("shoppingSelect");
  const ids = Object.keys(state.shoppings);
  if (ids.length === 0) {
    sel.innerHTML = '<option value="">— nenhum —</option>';
    document.getElementById("shoppingMeta").textContent = "";
    return;
  }
  sel.innerHTML = ids.map(id => {
    const s = state.shoppings[id];
    return '<option value="'+id+'" '+(id===state.activeShoppingId?"selected":"")+'>'+escapeHtml(s.nome)+'</option>';
  }).join("");
  const cur = state.shoppings[state.activeShoppingId];
  if (cur) {
    document.getElementById("shoppingMeta").innerHTML =
      (cur.cidade||"—") + " · " + (cur.cluster||"sem cluster") + "<br>" +
      (cur.abl ? Number(cur.abl).toLocaleString("pt-BR")+" m²" : "");
  }
}

function changeShopping(id) {
  state.activeShoppingId = id;
  if (!state.dbs[id]) {
    state.dbs[id] = {};
    Object.keys(DATABASES).forEach(k => {
      if (DATABASES[k].scope === "shopping") state.dbs[id][k] = [];
    });
  }
  saveState();
  renderShoppingSwitcher();
  renderHome();
  if (document.getElementById("shopping").classList.contains("active")) loadShoppingProfile();
  toast("Ativo: " + state.shoppings[id].nome);
}

function openShoppingModal() { document.getElementById("modalShopping").classList.add("active"); }
function closeShoppingModal() {
  document.getElementById("modalShopping").classList.remove("active");
  ["newSh_nome","newSh_cidade","newSh_estado"].forEach(id => document.getElementById(id).value = "");
  document.getElementById("newSh_cluster").value = "";
}

async function createShopping() {
  const nome = document.getElementById("newSh_nome").value.trim();
  const cidade = document.getElementById("newSh_cidade").value.trim();
  const cluster = document.getElementById("newSh_cluster").value;
  if (!nome || !cidade || !cluster) { toast("Preencha nome, cidade, cluster", "error"); return; }
  const id = nome.toLowerCase().replace(/[^a-z0-9]/g,"-") + "-" + Date.now().toString(36);
  state.shoppings[id] = {
    id, nome, cidade, estado:document.getElementById("newSh_estado").value.trim(),
    cluster, batalhas:[], operador:"", endereco:"", abl:"", lojas:"", ano:"", reforma:"",
    vacancia:"", abl_vaga:"", target:"", concorrencia:"", fortes:"", lacunas:"", saidas:"", mix:""
  };
  state.activeShoppingId = id;
  state.dbs[id] = {};
  Object.keys(DATABASES).forEach(k => {
    if (DATABASES[k].scope === "shopping") state.dbs[id][k] = [];
  });
  await saveState();
  renderShoppingSwitcher();
  renderHome();
  closeShoppingModal();
  toast("Shopping criado: " + nome, "success");
  navigate("shopping");
}

async function confirmDeleteShopping() {
  const cur = state.shoppings[state.activeShoppingId];
  if (!cur) return;
  if (!confirm('Excluir "'+cur.nome+'"? Inclui bases.')) return;
  delete state.shoppings[state.activeShoppingId];
  delete state.dbs[state.activeShoppingId];
  state.activeShoppingId = Object.keys(state.shoppings)[0] || null;
  await saveState();
  renderShoppingSwitcher();
  renderHome();
  navigate("home");
  toast("Excluído");
}

function loadShoppingProfile() {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) return;
  ["nome","cidade","estado","endereco","cluster","operador","abl","lojas","ano","reforma","vacancia","abl_vaga","target","concorrencia","fortes","lacunas","saidas","mix"].forEach(k => {
    const el = document.getElementById("sh_" + k);
    if (el) el.value = s[k] || "";
  });
  document.querySelectorAll("#sh_batalhas_group .pill-check").forEach(p => {
    const cb = p.querySelector("input");
    cb.checked = (s.batalhas||[]).includes(cb.value);
    p.classList.toggle("checked", cb.checked);
  });
}

async function saveShopping() {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) return;
  ["nome","cidade","estado","endereco","cluster","operador","abl","lojas","ano","reforma","vacancia","abl_vaga","target","concorrencia","fortes","lacunas","saidas","mix"].forEach(k => {
    const el = document.getElementById("sh_" + k);
    if (el) s[k] = el.value;
  });
  s.batalhas = Array.from(document.querySelectorAll("#sh_batalhas_group input:checked")).map(i => i.value);
  await saveState();
  renderShoppingSwitcher();
  document.getElementById("shoppingSaveStatus").textContent = "Salvo · " + new Date().toLocaleTimeString("pt-BR");
  toast("Perfil salvo", "success");
}

// =================== BUILD SECTIONS ===================
function buildAllSections() {
  let html = "";

  // Bases (7)
  Object.keys(DATABASES).forEach(dbKey => {
    const db = DATABASES[dbKey];
    html += '<section id="db-'+dbKey+'" class="section">';
