// =================== EXECUTION ===================
async function executeBriefing(sectionId) {
  const s = state.shoppings[state.activeShoppingId];
  if (!s) { toast("Selecione um shopping", "error"); return; }
  if (!s.cluster) { toast("Defina o cluster", "error"); navigate("shopping"); return; }

  const built = buildPromptForSection(sectionId);
  if (!built) return;

  if (!apiConfig.key) {
    if (confirm("API não configurada. Baixar prompt para colar manualmente?")) {
      downloadPromptText(built.prompt, built.label);
    } else openApiModal();
    return;
  }

  const btn = document.getElementById("btn-" + sectionId);
  const origText = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="streaming-indicator"><span class="pulse"></span>Executando...</span>';

  const section = document.getElementById(sectionId);
  let outputBlock = section.querySelector(".output-block");
  if (outputBlock) outputBlock.remove();
  outputBlock = document.createElement("div");
  outputBlock.className = "output-block";
  outputBlock.innerHTML =
    '<div class="output-bar">' +
      '<span class="label">▸ ' + escapeHtml(built.label) + ' · ' + escapeHtml(s.nome) + '</span>' +
      '<div class="actions-mini">' +
        '<button onclick="copyOutput(this)">Copiar</button>' +
        '<button onclick="downloadOutput(this)">↓ MD</button>' +
      '</div>' +
    '</div>' +
    '<div class="output-content"><div class="streaming-indicator"><span class="pulse"></span>Aguardando API...</div></div>';
  section.querySelector(".card").appendChild(outputBlock);
  outputBlock.scrollIntoView({behavior:"smooth", block:"center"});

  const startTime = Date.now();
  try {
    const payload = {
      model: apiConfig.model,
      max_tokens: apiConfig.maxTokens,
      messages: [{role:"user", content: built.prompt}]
    };
    if (apiConfig.webSearch) payload.tools = [{type:"web_search_20250305", name:"web_search"}];
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method:"POST",
      headers:{ "Content-Type":"application/json","x-api-key":apiConfig.key,
        "anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},
      body:JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message || "Erro API");
    const text = (data.content || []).filter(b => b.type === "text").map(b => b.text).join("\n\n");
    const elapsed = ((Date.now() - startTime)/1000).toFixed(1);
    const usage = data.usage || {};
    const cost = calculateCost(usage, apiConfig.model);

    // Parse ADD_TO_DB
    const {cleanText, suggestions} = parseAddToDb(text);

    state.history.push({
      ts: Date.now(), shoppingId: s.id, shoppingNome: s.nome,
      type: built.type, sectionId, label: built.label,
      prompt: built.prompt, output: text, usage, cost, elapsed,
      model: apiConfig.model, webSearchUsed: apiConfig.webSearch,
      suggestions
    });
    if (state.history.length > 50) state.history = state.history.slice(-50);
    await saveState();

    // Render output: cleanText + suggestions
    const contentDiv = outputBlock.querySelector(".output-content");
    let outputHtml = renderMarkdown(cleanText);
    if (suggestions.length > 0) {
      outputHtml += renderSuggestions(suggestions);
    }
    contentDiv.innerHTML = outputHtml;

    const stats = document.createElement("div");
    stats.className = "stats-bar";
    stats.innerHTML =
      '<span class="stat">Modelo: <span class="v">'+apiConfig.model.split("-").slice(1,3).join(" ")+'</span></span>' +
      '<span class="stat">Tokens in: <span class="v">'+(usage.input_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tokens out: <span class="v">'+(usage.output_tokens||0).toLocaleString("pt-BR")+'</span></span>' +
      '<span class="stat">Tempo: <span class="v">'+elapsed+'s</span></span>' +
      '<span class="stat">Custo: <span class="v">$'+cost.toFixed(3)+'</span></span>' +
      (suggestions.length > 0 ? '<span class="stat">Sugestões: <span class="v" style="color:var(--moss);">'+suggestions.length+'</span></span>' : '');
    outputBlock.appendChild(stats);
    toast("✓ Concluído em " + elapsed + "s" + (suggestions.length>0 ? " · "+suggestions.length+" sugestões" : ""), "success");
    renderHome();
