  }
}

function calculateCost(usage, model) {
  const p = PRICING[model] || PRICING["claude-sonnet-4-6-20250929"];
  return (usage.input_tokens || 0) / 1e6 * p.input + (usage.output_tokens || 0) / 1e6 * p.output;
}

// =================== AUTO-CADASTRO PARSER ===================
function parseAddToDb(text) {
  // Procura blocos: ```ADD_TO_DB:<dbKey>\n<JSON>\n```
  // Ou variações: ```add_to_db:..., ADD_TO_DB:..., etc.
  const suggestions = [];
  const regex = /```\s*ADD_TO_DB\s*:\s*([a-z_]+)\s*\n([\s\S]*?)```/gi;
  let cleanText = text;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const dbKey = match[1].toLowerCase().trim();
    const jsonRaw = match[2].trim();
    if (!DATABASES[dbKey]) continue;
    try {
      const parsed = JSON.parse(jsonRaw);
      suggestions.push({
        id: "sug_" + Date.now().toString(36) + "_" + suggestions.length + Math.random().toString(36).substr(2,3),
        dbKey,
        data: parsed,
        added: false
      });
    } catch(e) {
      // Tenta aceitar JSON com aspas simples ou trailing comma comum em LLM output
      try {
        const fixed = jsonRaw.replace(/'/g, '"').replace(/,(\s*[}\]])/g, "$1");
        const parsed = JSON.parse(fixed);
        suggestions.push({
          id: "sug_" + Date.now().toString(36) + "_" + suggestions.length,
          dbKey, data: parsed, added: false
        });
      } catch(e2) {
        console.warn("JSON inválido em ADD_TO_DB:", jsonRaw, e2.message);
      }
    }
  }
  // Remove os blocos do texto
  cleanText = text.replace(regex, "").trim();
  return {cleanText, suggestions};
}

function renderSuggestions(suggestions) {
  let html = '<div class="add-suggestions">';
  html += '<div class="title">Auto-cadastro · '+suggestions.length+' sugestão(ões) detectada(s)</div>';
  suggestions.forEach(sug => {
    const db = DATABASES[sug.dbKey];
    const dbName = db ? db.title : sug.dbKey;
    const labelF = db ? db.label_field : null;
    const previewName = labelF && sug.data[labelF] ? sug.data[labelF] : Object.values(sug.data)[0] || "(sem nome)";
    const previewFields = Object.entries(sug.data).slice(0, 4).map(([k,v]) => k+": "+(Array.isArray(v)?v.join("/"):v)).join(" · ");
    html += '<div class="add-suggestion-card" id="sug-card-'+sug.id+'">';
    html += '<div class="info">';
    html += '<div class="target">→ '+escapeHtml(dbName)+'</div>';
