    if (!file) return;
    try {
      const text = await file.text();
      let newRecords;
      if (format === "json") {
        const data = JSON.parse(text);
        newRecords = Array.isArray(data) ? data : (data.records || []);
      } else {
        newRecords = parseCsv(text, db);
      }
      if (!newRecords || newRecords.length === 0) throw new Error("Arquivo sem registros válidos");
      const choice = confirm("Importar "+newRecords.length+" registros para "+db.title+"?\n\nOK = MERGE (adicionar aos existentes)\nCancelar = SUBSTITUIR todos os existentes");
      const existing = getDbRecords(dbKey);
      const finalRecords = choice ? existing.concat(newRecords.map(r => {
        if (!r.id) r.id = "rec_" + Date.now().toString(36) + Math.random().toString(36).substr(2,5);
        return r;
      })) : newRecords.map(r => {
        if (!r.id) r.id = "rec_" + Date.now().toString(36) + Math.random().toString(36).substr(2,5);
        return r;
      });
      saveDbRecords(dbKey, finalRecords);
