  --rule:#2a313a; --rule-soft:#d4cdba; --accent:#c8553d; --accent-2:#d99857;
  --gold:#c9a55c; --moss:#4a5d3a; --steel:#5c6878; --plum:#8b4a8b;
  --shadow:0 1px 0 rgba(13,17,23,0.06),0 12px 24px -8px rgba(13,17,23,0.18);
