      " | Lojas: " + (s.lojas || "n.v.") + " | Vacância: " + (s.vacancia ? s.vacancia+"%" : "n.v.") +
      (s.abl_vaga ? " ("+Number(s.abl_vaga).toLocaleString("pt-BR")+"m²)" : "")
  ];
