    else if (inp.tagName === "SELECT") inp.selectedIndex = 0;
    else inp.value = "";
  });
}

// =================== EVENTS / INIT ===================
document.addEventListener("click", e => {
  const pill = e.target.closest(".pill-check");
  if (pill && pill.querySelector("input")) {
    const cb = pill.querySelector("input");
