  // 3 colunas à direita
  const cols = [
    { tag: "PRÓS", color: "1F8A5F", items: meta.pros },
    { tag: "CONTRAS", color: "B85042", items: meta.cons },
    { tag: "RISCOS OCULTOS", color: ACCENT, items: meta.hidden },
  ];

  const colW = 2.85;
  const colStart = 4.25;
  const colGap = 0.15;

  cols.forEach((c, i) => {
    const x = colStart + i * (colW + colGap);
