  cols.forEach((c, i) => {
    const x = colStart + i * (colW + colGap);
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 2.1, w: colW, h: 4.6,
      fill: { color: LIGHT_GRAY }, line: { color: LIGHT_GRAY, width: 0 },
