import React, { useState, useMemo } from "react";

// ============================================================
// SISTEMA DE CALIBRAÇÃO — BJJ / Força / Longevidade
// Baseado em: Attia (Outlive), Galpin, McGill, literatura peer-reviewed
// ============================================================

const FONTS = `
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,800&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');
* { -webkit-font-smoothing: antialiased; }
`;

// ---------- LÓGICA DE CÁLCULO ----------

function calculate(inputs) {
  const {
    age, weight, height, sex, bodyFat,
    goal, phase, bjjDays, strengthDays, cardioDays, level,
    injuries
  } = inputs;

  const w = Number(weight) || 0;
  const a = Number(age) || 0;

  // --- Cenário semanal (do arquivo de periodização) ---
  let scenario;
  if (bjjDays >= 4) scenario = "A";
  else if (bjjDays >= 2) scenario = "B";
  else scenario = "C";

  // --- TDEE / Calorias (Attia + literatura) ---
  // Manutenção = peso × 30-35 kcal (ativo)
  const totalTraining = bjjDays + strengthDays + cardioDays;
  const tdeeFactor = totalTraining >= 6 ? 34 : totalTraining >= 4 ? 32 : 30;
  const maintenance = Math.round(w * tdeeFactor);

  let calLow, calHigh;
  if (phase === "cutting") {
    calLow = maintenance - 500;
    calHigh = maintenance - 300;
  } else if (phase === "bulking") {
    calLow = maintenance + 200;
    calHigh = maintenance + 400;
  } else {
    calLow = maintenance - 100;
    calHigh = maintenance + 100;
  }

  // --- Proteína (Morton 2018; Helms 2014; Phillips 2016) ---
  let pLow = 1.6, pHigh = 2.2;
  if (phase === "cutting") { pLow = 2.0; pHigh = 2.4; }
  if (a >= 50) { pLow = Math.max(pLow, 2.0); pHigh = Math.max(pHigh, 2.2); }
  const proteinLow = Math.round(pLow * w);
  const proteinHigh = Math.round(pHigh * w);

  // --- Carbs ---
  const carbsHardLow = Math.round(3 * w);
  const carbsHardHigh = Math.round(6 * w);
  const carbsLightLow = Math.round(2 * w);
  const carbsLightHigh = Math.round(4 * w);

  // --- Gordura ---
  const fatLow = Math.round(0.8 * w);
  const fatHigh = Math.round(1.2 * w);

  // --- Força (volume e frequência) ---
  let strengthSets, strengthFocus;
  if (scenario === "A") {
    strengthSets = "6–10 séries/sessão (volume baixo, alta qualidade)";
    strengthFocus = "2x/semana, full body ou upper/lower. Prioridade: BJJ.";
  } else if (scenario === "B") {
    strengthSets = "8–14 séries/sessão";
    strengthFocus = "2–3x/semana, full body. Mais espaço para hipertrofia.";
  } else {
    strengthSets = "10–14 séries/sessão";
    strengthFocus = "2x/semana, full body. Mínimo viável p/ manter massa.";
  }

  // --- Cardio (Attia: Zone 2 + VO2max) ---
  const z2Sessions = scenario === "A" ? 1 : scenario === "B" ? 2 : 1;
  const vo2Sessions = totalTraining >= 6 ? 1 : 1;

  // --- Prehab (McGill + lesão específica) ---
  const prehab = [];
  prehab.push({ area: "Base diária", items: ["McGill Big 3 (curl-up, side plank, bird-dog) — 5–10 min", "CARs de pescoço, ombro, quadril — 3–5 min"] });
  if (injuries.lombar) prehab.push({ area: "Lombar", items: ["McGill Big 3 diário, sem falhar", "Dead bug 2x8 por lado", "Evitar flexão repetida sob carga (sit-ups, GHD)", "Hinge bem ensinado antes de carregar"] });
  if (injuries.joelho) prehab.push({ area: "Joelho", items: ["ATG split squat 2x8/perna (sem dor)", "Tibialis raises 3x20", "Nordic curl excêntrico 2x5", "Step-down lento (5s descida) 2x8"] });
  if (injuries.ombro) prehab.push({ area: "Ombro", items: ["Scapular pull-up / dip 3x8", "Sleeper stretch 30s/lado", "Band pull-aparts 2x15", "Dead hang 60s/dia acumulado"] });
  if (injuries.cervical) prehab.push({ area: "Cervical", items: ["Isometrias 4 direções, 3x30s cada, 2–3x/sem", "Evitar wrestler's bridge sem base", "Reforço de trapézio (shrugs leves)"] });
  prehab.push({ area: "BJJ sempre", items: ["Pescoço isométrico 3x30s (4 direções) 2x/sem", "Dead hang 60s/dia (grip + saúde do ombro)", "Tindão pince ou rice bucket 1x/sem"] });

  // --- Sinais de alerta personalizados ---
  const flags = [];

  if (a >= 45 && phase === "cutting" && bjjDays >= 4 && strengthDays >= 2) {
    flags.push({
      level: "alto",
      text: "Risco de RED-S: 45+ anos + cutting + volume alto de treino. Use deficit suave (–300 kcal max), proteína no topo da faixa (2.2–2.4 g/kg) e monitore libido, sono, FC repouso. Mountjoy et al., Br J Sports Med 2018."
    });
  }
  if (totalTraining >= 7) {
    flags.push({
      level: "alto",
      text: "Carga semanal ≥7 sessões. Recuperação será o gargalo. Reserve 1 dia totalmente off e considere reduzir cardio antes de força/BJJ."
    });
  }
  if (bjjDays >= 4 && cardioDays >= 2 && phase === "cutting") {
    flags.push({
      level: "médio",
      text: "BJJ pesado + cardio + cutting empilhados. Risco de interferência (Wilson 2012) + queda de performance. Considere cortar VO2max em fases de cutting."
    });
  }
  if (phase === "bulking" && goal === "longevity") {
    flags.push({
      level: "médio",
      text: "Bulk + foco em longevidade conflitam parcialmente. Surplus modesto (+200 kcal) preserva marcadores metabólicos. Evite bulk agressivo."
    });
  }
  if (a >= 50 && strengthDays < 2) {
    flags.push({
      level: "alto",
      text: "50+ anos com menos de 2x força/semana é insuficiente p/ combater sarcopenia (Volpi 2004). Mínimo viável: 2x/sem com cargas progressivas."
    });
  }
  if (bjjDays === 0 && goal === "bjj") {
    flags.push({ level: "alto", text: "Sem BJJ na semana mas objetivo é BJJ. Especificidade ganha. Inclua ao menos 2x/semana." });
  }
  if (injuries.lombar && strengthDays >= 2) {
    flags.push({
      level: "médio",
      text: "Histórico de lombar + força ≥2x/sem. Hinge (deadlift, RDL) só com técnica validada por profissional. Em dúvida, troque por kettlebell swing ou hip thrust."
    });
  }
  if (a >= 40 && cardioDays === 0) {
    flags.push({
      level: "médio",
      text: "40+ anos sem cardio estruturado. VO2max é o preditor isolado mais forte de mortalidade (Mandsager 2018). Inclua 1x Zone 2 e 1x VO2max/semana."
    });
  }
  if (level === "begin" && totalTraining >= 6) {
    flags.push({ level: "alto", text: "Iniciante com volume alto. Risco de overtraining e lesão. Comece com 3–4 sessões/sem e progrida." });
  }

  // --- Template semanal concreto ---
  const week = buildWeekTemplate(scenario, bjjDays, strengthDays, cardioDays);

  return {
    scenario, maintenance, calLow, calHigh,
    proteinLow, proteinHigh,
    carbsHardLow, carbsHardHigh, carbsLightLow, carbsLightHigh,
    fatLow, fatHigh,
    strengthSets, strengthFocus,
    z2Sessions, vo2Sessions,
    prehab, flags, week,
    totalTraining
  };
}

function buildWeekTemplate(scenario, bjjDays, strengthDays, cardioDays) {
  const days = ["SEG", "TER", "QUA", "QUI", "SEX", "SÁB", "DOM"];
  let plan;
  if (scenario === "A") {
    plan = {
      SEG: ["Zone 2 30–45min (opc.)", "BJJ"],
      TER: ["Força A (lower)"],
      QUA: ["BJJ"],
      QUI: ["Força B (upper)", "BJJ técnico leve"],
      SEX: ["VO2max 4x4 (Norwegian)"],
      "SÁB": ["BJJ (rolamento duro)"],
      DOM: ["Mobilidade + caminhada"],
    };
  } else if (scenario === "B") {
    plan = {
      SEG: ["Força A (full body)"],
      TER: ["BJJ"],
      QUA: ["Zone 2 45–60min"],
      QUI: ["BJJ"],
      SEX: ["Força B (full body)"],
      "SÁB": ["BJJ ou VO2max"],
      DOM: ["Mobilidade"],
    };
  } else {
    plan = {
      SEG: ["Força A (full body, 40–50min)"],
      TER: ["BJJ"],
      QUA: ["Zone 2 longo (60–75min) ou caminhada inclinada"],
      QUI: ["Força B (full body, 40–50min)"],
      SEX: ["BJJ"],
      "SÁB": ["Mobilidade + caminhada"],
      DOM: ["Off completo"],
    };
  }
  return plan;
}

// ---------- GERADOR DE SYSTEM PROMPT ----------

function buildSystemPrompt(inputs, calc) {
  const goalMap = {
    bjj: "Performance no jiu-jitsu (gás, força funcional, prevenção de lesão)",
    hyper: "Hipertrofia e força progressiva sem prejudicar BJJ",
    longevity: "Longevidade saudável (VO2max alto, força preservada, marcadores metabólicos)",
    recomp: "Recomposição corporal (perder gordura, manter/ganhar massa magra)"
  };
  const phaseMap = { cutting: "Cutting (deficit calórico controlado)", maintain: "Manutenção", bulking: "Bulking suave" };
  const levelMap = { begin: "Iniciante", inter: "Intermediário", adv: "Avançado" };
  const injuryList = Object.entries(inputs.injuries).filter(([,v]) => v).map(([k]) => k).join(", ") || "nenhuma reportada";

  return `Você é meu coach de performance física focado em jiu-jitsu, musculação e longevidade.

REFERENCIAL CIENTÍFICO (em ordem de prioridade)
1. Peter Attia (Outlive, Medicine 3.0): Zone 2, VO2max, força + estabilidade, proteína, sono.
2. Andy Galpin / Andrew Huberman: periodização, recuperação, protocolos neurais, sono.
3. Stuart McGill: saúde da coluna e prevenção de lesão para grappling.
4. Literatura peer-reviewed sempre que possível.

NÃO use Gary Brecka, biohacks sem evidência, ou claims de marketing disfarçados de ciência. Se eu pedir algo nessa linha, me avise.

MEU PERFIL
- Idade: ${inputs.age} anos
- Peso: ${inputs.weight} kg | Altura: ${inputs.height} cm | Sexo: ${inputs.sex === "M" ? "Masculino" : "Feminino"}${inputs.bodyFat ? ` | ~${inputs.bodyFat}% gordura` : ""}
- Nível: ${levelMap[inputs.level]}
- Lesões/limitações: ${injuryList}

OBJETIVO ATIVO
- Foco principal: ${goalMap[inputs.goal]}
- Fase nutricional: ${phaseMap[inputs.phase]}

DISPONIBILIDADE SEMANAL
- BJJ: ${inputs.bjjDays}x/semana (prioridade — musculação serve ao tatame)
- Força: ${inputs.strengthDays}x/semana
- Cardio estruturado: ${inputs.cardioDays}x/semana

ALVOS CALIBRADOS (calculados a partir do meu perfil)
- Manutenção calórica: ~${calc.maintenance} kcal/dia
- Meta calórica atual: ${calc.calLow}–${calc.calHigh} kcal/dia
- Proteína: ${calc.proteinLow}–${calc.proteinHigh} g/dia (${(calc.proteinLow/inputs.weight).toFixed(1)}–${(calc.proteinHigh/inputs.weight).toFixed(1)} g/kg)
- Carbo dia treino duro: ${calc.carbsHardLow}–${calc.carbsHardHigh} g
- Carbo dia leve: ${calc.carbsLightLow}–${calc.carbsLightHigh} g
- Gordura: ${calc.fatLow}–${calc.fatHigh} g
- Template semanal: Cenário ${calc.scenario}

COMO RESPONDER
- Objetivo, sem floreio. Direto ao ponto.
- Cite a fonte quando der um número, estudo ou claim específico.
- Se a evidência for fraca, diga "evidência fraca" ou "opinião de X".
- Ofereça quando fizer sentido 2 versões: ótima e mínima viável (semanas corridas).
- BJJ é prioridade. Periodize tudo em torno dele.
- Não é aconselhamento médico. Para sintomas, lesão ou exames fora da faixa, recomende consulta presencial.

CONFIANÇA
Ao final de respostas técnicas, classifique sua confiança 1–10. Abaixo de 7, sinalize por quê.`;
}

// ---------- COMPONENTES UI ----------

const styles = {
  page: {
    fontFamily: "'IBM Plex Sans', sans-serif",
    background: "#f4efe6",
    color: "#1a1817",
    minHeight: "100vh",
    paddingBottom: "60px"
  },
  display: { fontFamily: "'Fraunces', serif", fontWeight: 800, letterSpacing: "-0.02em", lineHeight: 1 },
  mono: { fontFamily: "'IBM Plex Mono', monospace" },
  accent: "#a63a1e",
  border: "#1a1817",
  paper: "#fbf7ee",
  dim: "#6a6560"
};

function SectionHeader({ num, title }) {
  return (
    <div className="flex items-baseline gap-3 mb-4 pb-2" style={{ borderBottom: `1px solid ${styles.border}` }}>
      <span style={{ ...styles.mono, fontSize: "11px", color: styles.dim, letterSpacing: "0.1em" }}>{num}</span>
      <h2 style={{ ...styles.display, fontSize: "22px" }}>{title}</h2>
    </div>
  );
}

function Field({ label, children, hint }) {
  return (
    <div className="mb-4">
      <label className="block mb-1.5" style={{ ...styles.mono, fontSize: "10px", letterSpacing: "0.12em", color: styles.dim, textTransform: "uppercase" }}>
        {label}
      </label>
      {children}
      {hint && <div className="mt-1" style={{ ...styles.mono, fontSize: "10px", color: styles.dim }}>{hint}</div>}
    </div>
  );
}

function inputStyle() {
  return {
    width: "100%",
    padding: "10px 12px",
    background: styles.paper,
    border: `1px solid ${styles.border}`,
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "15px",
    color: styles.border,
    outline: "none",
    borderRadius: 0
  };
}

function Radio({ name, value, current, onChange, label }) {
  const active = current === value;
  return (
    <button
      type="button"
      onClick={() => onChange(value)}
      style={{
        ...styles.mono,
        fontSize: "12px",
        padding: "8px 12px",
        border: `1px solid ${styles.border}`,
        background: active ? styles.border : "transparent",
        color: active ? styles.paper : styles.border,
        cursor: "pointer",
        letterSpacing: "0.04em",
        marginRight: "6px",
        marginBottom: "6px",
        textTransform: "uppercase"
      }}
    >
      {label}
    </button>
  );
}

function Check({ checked, onChange, label }) {
  return (
    <label className="flex items-center gap-2 mb-2" style={{ cursor: "pointer" }}>
      <span
        onClick={() => onChange(!checked)}
        style={{
          width: 18, height: 18,
          border: `1.5px solid ${styles.border}`,
          background: checked ? styles.border : "transparent",
          display: "inline-block",
          position: "relative"
        }}
      >
        {checked && <span style={{ position: "absolute", top: 1, left: 4, color: styles.paper, fontSize: 13 }}>✓</span>}
      </span>
      <span style={{ ...styles.mono, fontSize: 13 }}>{label}</span>
    </label>
  );
}

function OutputBlock({ label, children }) {
  return (
    <div className="mb-6 p-4" style={{ background: styles.paper, border: `1px solid ${styles.border}` }}>
      <div className="mb-3" style={{ ...styles.mono, fontSize: "10px", letterSpacing: "0.15em", color: styles.accent, textTransform: "uppercase", fontWeight: 600 }}>
        ◆ {label}
      </div>
      {children}
    </div>
  );
}

function DataRow({ k, v, accent }) {
  return (
    <div className="flex justify-between items-baseline py-1.5" style={{ borderBottom: `1px dashed ${styles.dim}40` }}>
      <span style={{ ...styles.mono, fontSize: 12, color: styles.dim }}>{k}</span>
      <span style={{ ...styles.mono, fontSize: 14, color: accent ? styles.accent : styles.border, fontWeight: 600 }}>{v}</span>
    </div>
  );
}

// ---------- COMPONENTE PRINCIPAL ----------

export default function CalibrationSystem() {
  const [inputs, setInputs] = useState({
    name: "",
    age: 35,
    weight: 80,
    height: 175,
    sex: "M",
    bodyFat: "",
    goal: "bjj",
    phase: "maintain",
    bjjDays: 3,
    strengthDays: 2,
    cardioDays: 1,
    level: "inter",
    injuries: { lombar: false, joelho: false, ombro: false, cervical: false }
  });

  const update = (k, v) => setInputs(p => ({ ...p, [k]: v }));
  const updateInjury = (k, v) => setInputs(p => ({ ...p, injuries: { ...p.injuries, [k]: v } }));

  const calc = useMemo(() => calculate(inputs), [inputs]);
  const sysPrompt = useMemo(() => buildSystemPrompt(inputs, calc), [inputs, calc]);

  const [copied, setCopied] = useState(false);
  const copyPrompt = () => {
    navigator.clipboard.writeText(sysPrompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div style={styles.page}>
      <style>{FONTS}</style>

      {/* HEADER */}
      <div className="px-5 pt-8 pb-6" style={{ borderBottom: `2px solid ${styles.border}` }}>
        <div style={{ ...styles.mono, fontSize: 10, letterSpacing: "0.2em", color: styles.dim, marginBottom: 8 }}>
          FIELD MANUAL · CALIBRATION SYSTEM v1.0
        </div>
        <h1 style={{ ...styles.display, fontSize: 38, lineHeight: 0.95, marginBottom: 8 }}>
          BJJ · Força · <em style={{ fontStyle: "italic", color: styles.accent }}>Longevidade</em>
        </h1>
        <p style={{ fontSize: 13, lineHeight: 1.5, maxWidth: 540, color: styles.dim }}>
          Sistema reutilizável baseado em Attia (Outlive), Galpin/Huberman e McGill. Entre seus dados → recebe plano calibrado, alvos nutricionais, semana sugerida e um <em>system prompt</em> pronto para usar como coach AI em qualquer plataforma.
        </p>
      </div>

      <div className="px-5 py-6 grid gap-8" style={{ gridTemplateColumns: "1fr", maxWidth: 1200, margin: "0 auto" }}>

        {/* === INPUTS === */}
        <div>
          <SectionHeader num="01 / 04" title="Perfil" />
          <div className="grid grid-cols-2 gap-3">
            <Field label="Idade"><input style={inputStyle()} type="number" value={inputs.age} onChange={e => update("age", Number(e.target.value))} /></Field>
            <Field label="Peso (kg)"><input style={inputStyle()} type="number" value={inputs.weight} onChange={e => update("weight", Number(e.target.value))} /></Field>
            <Field label="Altura (cm)"><input style={inputStyle()} type="number" value={inputs.height} onChange={e => update("height", Number(e.target.value))} /></Field>
            <Field label="% gordura (opc.)" hint="se souber (bioimpedância)"><input style={inputStyle()} type="number" value={inputs.bodyFat} onChange={e => update("bodyFat", e.target.value)} /></Field>
          </div>
          <Field label="Sexo">
            <Radio current={inputs.sex} value="M" onChange={v => update("sex", v)} label="Masc." />
            <Radio current={inputs.sex} value="F" onChange={v => update("sex", v)} label="Fem." />
          </Field>
          <Field label="Nível de experiência">
