import csv, unicodedata, json

def norm(s):
    s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower().strip()
    return s

def load(y):
    with open(f'data/495_{y}.csv',encoding='utf-8-sig',errors='replace') as f:
        rd=csv.reader(f,delimiter=';')
        hdr=next(rd)
        rows=[r for r in rd if r and r[0].strip()]
    # indices of numeric cols that are age>=15
    idx=[]
    for i,c in enumerate(hdr):
        if i<9: continue
        cl=c.lower()
        # extract starting age
        import re
        m=re.search(r'(\d+)\s*a\s*\d+\s*anos', cl) or re.search(r'(\d+)\s*anos ou mais', cl)
        if not m: 
            continue
        start=int(m.group(1))
        if start>=15:
            idx.append(i)
    data={}
    meta={}
    for r in rows:
        b=r[0].strip()
        meta[norm(b)]=(b, r[4].strip(), r[7].strip())  # nome, ra, ap
        tot=0
        for i in idx:
            v=r[i].strip().replace('.','').replace(' ','')
            if v in ('','-','...','X'): v='0'
            try: tot+=int(v)
            except: 
                try: tot+=int(float(v.replace(',','.')))
                except: pass
        data[norm(b)]=tot
    return data,meta,len(idx)

D={}; M={}
for y in ['2000','2010','2022']:
    D[y],M[y],n=load(y)
    print(f'{y}: {len(D[y])} bairros, {n} colunas 15+ somadas, total cidade(15+ alfab)={sum(D[y].values()):,}')

clusters={
 'A — Méier/Inhaúma (NorteShopping + Nova América)':['Cachambi','Del Castilho','Maria da Graça','Todos os Santos','Méier','Engenho de Dentro'],
 'B — Penha/Irajá (Carioca Shopping)':['Vila da Penha','Vila Kosmos','Irajá','Penha','Olaria','Vista Alegre'],
 'C — Madureira (Madureira Shopping)':['Madureira','Cascadura','Oswaldo Cruz','Campinho','Vaz Lobo','Quintino Bocaiúva'],
}

print('\n===== CHECK: bairros encontrados + RA/AP (do CSV 2022) =====')
for cl,bs in clusters.items():
    print('\n##',cl)
    for b in bs:
        k=norm(b)
        if k in M['2022']:
            nome,ra,ap=M['2022'][k]
            print(f'  OK  {b:20s} -> RA: {ra:18s} | {ap}')
        else:
            # try fuzzy
            cand=[kk for kk in M['2022'] if norm(b) in kk or kk in norm(b)]
            print(f'  ??  {b:20s} -> NAO ACHADO. candidatos: {cand}')

print('\n===== Proxy: alfabetizados 15+ por bairro e ano =====')
rows_out=[]
for cl,bs in clusters.items():
    print('\n##',cl)
    cl_tot={'2000':0,'2010':0,'2022':0}
    for b in bs:
        k=norm(b)
        vals={y:D[y].get(k) for y in ['2000','2010','2022']}
        for y in ['2000','2010','2022']:
            if vals[y] is not None: cl_tot[y]+=vals[y]
        print(f'  {b:20s} 2000={vals["2000"]!s:>7}  2010={vals["2010"]!s:>7}  2022={vals["2022"]!s:>7}')
        rows_out.append([cl,b,vals['2000'],vals['2010'],vals['2022']])
    def pct(a,b): 
        return f'{(b/a-1)*100:+.1f}%' if a else 'n/d'
    print(f'  >> CLUSTER {cl_tot["2000"]:,} -> {cl_tot["2010"]:,} -> {cl_tot["2022"]:,}  | 00-10 {pct(cl_tot["2000"],cl_tot["2010"])}  10-22 {pct(cl_tot["2010"],cl_tot["2022"])}  00-22 {pct(cl_tot["2000"],cl_tot["2022"])}')

json.dump(rows_out,open('/home/claude/proxy_rows.json','w'))
