python3 << 'EOF'
import pandas as pd, unicodedata, json
def norm(s): return unicodedata.normalize('NFKD',str(s)).encode('ascii','ignore').decode().lower().strip()
clusters={'A':['Cachambi','Del Castilho','Maria da Graça','Todos os Santos','Méier','Engenho de Dentro'],
 'B':['Vila da Penha','Vila Kosmos','Irajá','Penha','Olaria','Vista Alegre'],
 'C':['Madureira','Cascadura','Osvaldo Cruz','Campinho','Vaz Lobo','Quintino Bocaiúva']}
b2c={norm(b):cl for cl,bs in clusters.items() for b in bs}
canon={norm(b):b for bs in clusters.values() for b in bs}

def load(sh):
    d=pd.read_excel('1176.xls',sheet_name=sh,header=None)
    out={}
    for i in range(5,d.shape[0]):
        lab=d.iloc[i,0]
        if pd.isna(lab): continue
        vals=[d.iloc[i,c] for c in range(1,6)]  # 5 quintis
        if any(pd.isna(v) for v in vals): continue
        mean5=sum(float(v) for v in vals)/5.0
        ratio=float(d.iloc[i,5])/float(d.iloc[i,1]) if float(d.iloc[i,1]) else None  # 5ºquinto/1ºquinto
        out[str(lab).strip()]={'mean':mean5,'q1':float(d.iloc[i,1]),'q5':float(d.iloc[i,5]),'ratio':ratio}
    return out
Y={'1991':load('Bairros_1991'),'2000':load('Bairros_2000'),'2010':load('Bairros_2010')}

# bairros isoláveis = label normalizado == nome do bairro, nos 3 anos
standalone=[]
for nb,b in canon.items():
    ok=all(any(norm(lab)==nb for lab in Y[y]) for y in Y)
    if ok: standalone.append(b)
print("ISOLÁVEIS nos 3 anos (",len(standalone),"):")
for b in standalone: print("  ",b2c[norm(b)],b)

# renda média por bairro isolável
inc={}
for b in standalone:
    nb=norm(b); inc[b]={}
    for y in Y:
        for lab,v in Y[y].items():
            if norm(lab)==nb: inc[b][y]=v['mean']
print("\nRenda domiciliar per capita média (R$ const., FJP):")
for b in standalone:
    print(f"  [{b2c[norm(b)]}] {b:18s} 1991={inc[b]['1991']:7.0f}  2000={inc[b]['2000']:7.0f}  2010={inc[b]['2010']:7.0f}  | 91→10 {(inc[b]['2010']/inc[b]['1991']-1)*100:+.0f}%")

# pop para ponderar (do trabalho anterior)
pop=json.load(open('/home/claude/work/out.json'))['rows']
popd={norm(r['bairro']):{y:int(r[y]) for y in ['1991','2000','2010']} for r in pop}

print("\nMédia ponderada por população — só bairros isoláveis (com cobertura):")
clusres={}
for cl in ['A','B','C']:
    bs=[b for b in standalone if b2c[norm(b)]==cl]
    cov=f"{len(bs)}/6"
    line={}
    for y in ['1991','2000','2010']:
        num=sum(inc[b][y]*popd[norm(b)][y] for b in bs)
        den=sum(popd[norm(b)][y] for b in bs)
        line[y]=num/den
    clusres[cl]={'cov':cov,'bairros':bs,**line}
    print(f"  Cluster {cl} (cobertura {cov}: {', '.join(bs)})")
    print(f"     1991={line['1991']:.0f}  2000={line['2000']:.0f}  2010={line['2010']:.0f}  | 91→10 {(line['2010']/line['1991']-1)*100:+.0f}%")

# Rio inteiro p/ referência (linha 6 das RAs = Rio de Janeiro)? usar média dos 5 quintis do Rio em cada aba RA
rio={}
for y,sh in [('1991','RA_1991'),('2000','RA_2000'),('2010','RA_2010')]:
    d=pd.read_excel('1176.xls',sheet_name=sh,header=None)
    for i in range(5,d.shape[0]):
        if str(d.iloc[i,1]).strip()=='Rio de Janeiro':
            rio[y]=sum(float(d.iloc[i,c]) for c in range(2,7))/5; break
print("\nRio (referência), média 5 quintis:",{y:round(v) for y,v in rio.items()})

json.dump({'inc':inc,'clus':clusres,'rio':rio,'b2c':{b:b2c[norm(b)] for b in standalone}},
          open('/home/claude/work/renda.json','w'))
print("\nok")
