<script>
(function(){
const $=s=>document.querySelector(s);
const brl=v=>(Number(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pct=v=>isFinite(v)?(v*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%':'—';
