  const est=custoEst(e,div);const custo=draftCusto!=null&&draftCusto!==''?Number(draftCusto):est;
  const acum=st.custoReal+(custo||0);
  const lim=(Number(regua.params.limite)||0)/100;const att=(Number(regua.params.atencao)||0)/100;
  const razao=div>0?acum/div:Infinity;const razaoEt=div>0&&custo!=null?custo/div:Infinity;
  const checks=[];
  checks.push({k:'seq',ok:true,t:`Sequência: ${st.idx===0?'primeira etapa da régua':'etapa '+st.idx+' concluída/N.A.'}`});
  const noPrazo=hoje>=eleg;checks.push({k:'prazo',ok:noPrazo,w:!noPrazo,t:noPrazo?`Prazo atingido (liberada desde ${fmtD(eleg)})`:`Prazo não atingido: libera em ${fmtD(eleg)} (${days(hoje,eleg)} dias). Antecipar exige justificativa.`});
  const aplica=e.aplica==='todas'||(e.aplica==='ativa'&&c.situacao==='ATIVA')||(e.aplica==='inativa'&&c.situacao==='INATIVA');
  checks.push({k:'aplica',ok:aplica,w:!aplica,t:aplica?'Etapa aplicável à situação da loja':`Etapa prevista só para loja ${e.aplica.toUpperCase()} — avaliar N.A.`});
  const minOk=div>=(Number(e.minDiv)||0);checks.push({k:'min',ok:minOk,w:!minOk,t:minOk?`Dívida acima do mínimo da etapa (${brl(e.minDiv)})`:`Dívida abaixo do mínimo da etapa (${brl(e.minDiv)})`});
  const defOk=e.definido||(draftCusto!=null&&draftCusto!=='');checks.push({k:'custo',ok:defOk,w:!defOk,t:defOk?'Custo estimado conhecido':'Custo desta etapa não cadastrado — informe uma estimativa (orçamento do jurídico) antes de decidir'});
  const alc=razao>lim;checks.push({k:'alcada',ok:!alc,bad:alc,t:alc?`Custo acumulado ${pct(razao)} da dívida, acima do limite de ${pct(lim)} — exige aprovação de alçada`:`Custo acumulado ${pct(razao)} da dívida, dentro do limite de ${pct(lim)}`});
  let verdict,cls;
  if(!defOk){verdict='Defina o custo antes de decidir';cls='c-warn'}
  else if(alc){verdict='Avançar só com aprovação de alçada';cls='c-bad'}
  else if(!aplica||!minOk){verdict='Avaliar marcar N.A. ou encerrar';cls='c-warn'}
  else if(!noPrazo){verdict='Aguardar o prazo da régua';cls='c-na'}
  else if(razao>lim*att){verdict='Seguir, na zona de atenção de custo';cls='c-warn'}
  else {verdict='Seguir para esta etapa';cls='c-ok'}
  return {e,st,div,est,custo,acum,razao,razaoEt,lim,att,eleg,noPrazo,aplica,minOk,defOk,alc,checks,verdict,cls,diasAtraso:c.vencimento?days(c.vencimento,hoje):0};
}

// ---------- render carteira ----------
function render(){renderKpis();renderLista();renderCaso();if(!$('#v-regua').hidden)renderRegua()}
function filtrados(){
  const sh=$('#f-shop').value,st=$('#f-st').value;
  return casos.filter(c=>(!sh||c.shopping===sh)&&(st==='todos'||(st==='abertos'?!c.encerrado:!!c.encerrado)))
   .sort((a,b)=>(Number(b.divida)||0)-(Number(a.divida)||0));
}
function renderKpis(){
  const ab=casos.filter(c=>!c.encerrado);
  const div=ab.reduce((s,c)=>s+(Number(c.divida)||0),0),pdd=ab.reduce((s,c)=>s+(Number(c.pdd)||0),0);
  const custo=ab.reduce((s,c)=>s+(regua?estadoCaso(c).custoReal:0),0);
  const atras=regua?ab.filter(c=>{const g=gate(c);return g&&g.noPrazo}).length:0;
  const alc=regua?ab.filter(c=>{const g=gate(c);return g&&g.alc}).length:0;
  $('#kpis').innerHTML=[
   ['Casos em aberto',ab.length.toLocaleString('pt-BR')],
   ['Dívida em cobrança',brl(div)],
   ['Valor em PDD',brl(pdd)],
   ['Custo de cobrança realizado',brl(custo)+` <span class="meta">${div?pct(custo/div):''}</span>`],
   ['Etapas liberadas para executar',atras.toLocaleString('pt-BR')],
   ['Pendentes de alçada',alc.toLocaleString('pt-BR')]
  ].map(([l,v])=>`<div class="kpi"><span class="lbl">${l}</span><span class="v">${v}</span></div>`).join('');
  const shops=[...new Set(casos.map(c=>c.shopping).filter(Boolean))].sort();const cur=$('#f-shop').value;
  $('#f-shop').innerHTML='<option value="">Todos os shoppings</option>'+shops.map(s=>`<option ${s===cur?'selected':''}>${esc(s)}</option>`).join('');
}
function barra(c){const et=etapasAtivas(),reg=c.etapas||{},st=estadoCaso(c);return '<div class="bar" aria-hidden="true">'+et.map((e,i)=>{const r=reg[e.id];const k=r&&r.status==='ok'?'ok':r&&r.status==='na'?'na':i===st.idx&&!c.encerrado?'cur':'';return `<i class="${k}" title="${esc(e.nome)}"></i>`}).join('')+'</div>'}
function renderLista(){
  const rows=filtrados();$('#lista-vazia').hidden=casos.length>0;
  $('#lista').innerHTML=rows.map(c=>{
    const st=regua?estadoCaso(c):null,g=regua&&!c.encerrado?gate(c):null;
    let etapa=c.encerrado?`<span class="chip c-na">Encerrado · ${esc(c.encerrado.motivo)}</span>`:st&&st.atual?`<span class="chip c-cur">${st.idx+1}. ${esc(st.atual.nome)}</span>`:st?'<span class="chip c-ok">Régua concluída</span>':'—';
    let prazo=g?(g.alc?'<span class="chip c-bad">Alçada</span>':g.noPrazo?'<span class="chip c-warn">Executar</span>':`<span class="chip c-na">${fmtD(g.eleg)}</span>`):'';
    return `<tr class="click ${c.id===selId?'sel':''}" data-id="${esc(c.id)}"><td><b>${esc(c.loja)}</b>${c.exemplo?'<span class="ex">EXEMPLO</span>':''}<div class="meta">${esc(c.luc)} · ${esc(c.situacao)}</div></td><td>${esc(c.shopping)}</td><td class="r num">${c.vencimento?days(c.vencimento,todayISO()):'—'}</td><td class="r num">${brl(c.divida)}</td><td class="r num">${st?brl(st.custoReal):'—'}</td><td>${etapa}</td><td>${regua?barra(c):''}</td><td>${prazo}</td></tr>`}).join('');
  document.querySelectorAll('#lista tr').forEach(tr=>tr.onclick=()=>{selId=tr.dataset.id;render();$('#caso').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'})});
}

// ---------- caso ----------
function renderCaso(){
  const box=$('#caso');const c=casos.find(x=>x.id===selId);
  if(!c||!regua){box.innerHTML='';return}
  const et=etapasAtivas(),reg=c.etapas||{},st=estadoCaso(c);const d=drafts[c.id]||(drafts[c.id]={});
  const g=!c.encerrado?gate(c,d.custo):null;
  const steps=et.map((e,i)=>{const r=reg[e.id];const k=r&&r.status==='ok'?'ok':r&&r.status==='na'?'na':i===st.idx&&!c.encerrado?'cur':'lock';
    const est=custoEst(e,Number(c.divida)||0);
    let det=r?`${r.status==='ok'?'Concluída':'N.A.'} em ${fmtD(r.data)} · dívida no momento ${brl(r.dividaMomento)} · custo ${brl(r.custoReal)} · acumulado ${brl(r.custoAcum)} (${pct(r.razao)})${r.alcada?` · alçada: ${esc(r.alcada)}`:''}${r.just?`<br>“${esc(r.just)}”`:''}`:`${esc(e.resp)} · D+${e.gatilho}${e.intervalo?` / +${e.intervalo}d da anterior`:''} · custo est. ${est==null?'<b>não cadastrado</b>':brl(est)}`;
    const chip=k==='ok'?'<span class="chip c-ok">OK</span>':k==='na'?'<span class="chip c-na">N.A.</span>':k==='cur'?'<span class="chip c-cur">Atual</span>':'<span class="chip c-na">Bloqueada</span>';
    return `<li class="${k}"><span class="dot">${i+1}</span><div style="min-width:0"><b>${esc(e.nome)}</b><div class="meta">${det}</div></div>${chip}</li>`}).join('');
  const lastDone=[...et].reverse().find(e=>reg[e.id]);
  box.innerHTML=`<div class="panel">
   <div class="row between"><div><span class="lbl">Caso selecionado</span><h2>${esc(c.loja)}${c.exemplo?'<span class="ex">EXEMPLO</span>':''}</h2><div class="meta">${esc(c.luc)} · ${esc(c.shopping)} · loja ${esc(c.situacao)} · ${c.garantia==='S'?'com garantia':'sem garantia'} · vencimento mais antigo ${fmtD(c.vencimento)} (${c.vencimento?days(c.vencimento,todayISO()):'—'} dias)</div></div>
   <div class="row"><label class="note">Dívida atual R$ <input id="c-div" class="n" type="number" step="0.01" value="${Number(c.divida)||0}"></label><label class="note">PDD R$ <input id="c-pdd" class="n" type="number" step="0.01" value="${Number(c.pdd)||0}"></label><button class="btn sm" id="c-savediv">Atualizar valores</button></div></div>
   <div class="case-grid">
    <div style="min-width:0;display:grid;gap:10px"><h3>Régua do caso · ${st.feitos}/${st.total} etapas</h3><ol class="steps">${steps}</ol>
     <div class="row">${lastDone&&!c.encerrado?`<button class="btn sm" id="c-undo">Desfazer “${esc(lastDone.nome)}”</button>`:''}${c.encerrado?`<button class="btn sm" id="c-reopen">Reabrir caso</button>`:''}<button class="btn sm danger" id="c-del">Excluir caso</button></div>
     <div id="c-confirm"></div>
     <label class="note" style="display:grid;gap:4px">Observações do caso<textarea id="c-obs">${esc(c.obs||'')}</textarea></label><div><button class="btn sm" id="c-saveobs">Salvar observação</button></div>
    </div>
    <div style="min-width:0">${c.encerrado?`<div class="gate"><h3>Caso encerrado</h3><p style="margin:0">${esc(c.encerrado.motivo)} em ${fmtD(c.encerrado.data)}. Valor ${brl(c.encerrado.valor)} · custo total de cobrança ${brl(st.custoReal)}.</p>${c.encerrado.just?`<p class="meta" style="margin:0">“${esc(c.encerrado.just)}”</p>`:''}</div>`:g?gateHTML(c,g,d):`<div class="gate"><h3>Régua concluída</h3><p style="margin:0">Todas as etapas foram executadas ou marcadas N.A. Encerre o caso abaixo.</p>${encerrarHTML(c)}</div>`}</div>
   </div></div>`;
  bindCaso(c,g);
}
function gateHTML(c,g,d){
  const w=Math.min(1,g.lim>0?g.razao/(g.lim*1.5):1);const mark=g.lim>0?Math.min(100,100/1.5):100;
  const mcls=g.alc?'bad':g.razao>g.lim*g.att?'warn':'';
  return `<div class="gate" aria-live="polite">
   <div class="row between"><div><span class="lbl">Decisão · próxima etapa ${g.st.idx+1} de ${g.st.total}</span><h3>${esc(g.e.nome)}</h3><div class="meta">${esc(g.e.resp)} · gatilho D+${g.e.gatilho} · ${g.diasAtraso} dias de atraso</div></div><span class="chip ${g.cls}">${g.verdict}</span></div>
   <div class="vs">
    <div><span class="lbl">Dívida no momento</span><span class="v">${brl(g.div)}</span></div>
    <div><span class="lbl">Custo da etapa</span><span class="v">${g.custo==null?'?':brl(g.custo)}</span><span class="meta">${g.custo==null?'não cadastrado':pct(g.razaoEt)+' da dívida'}</span></div>
    <div><span class="lbl">Já gasto no caso</span><span class="v">${brl(g.st.custoReal)}</span></div>
    <div><span class="lbl">Acumulado se seguir</span><span class="v">${brl(g.acum)}</span><span class="meta">${pct(g.razao)} da dívida</span></div>
   </div>
   <div><div class="row between meta"><span>Custo acumulado ÷ dívida</span><span>limite ${pct(g.lim)}</span></div><div class="meter" role="img" aria-label="Custo acumulado ${pct(g.razao)} da dívida, limite ${pct(g.lim)}"><span class="${mcls}" style="width:${(w*100).toFixed(1)}%"></span><b style="left:${mark}%"></b></div></div>
   <ul class="checks">${g.checks.map(k=>`<li><span class="chip ${k.bad?'c-bad':k.w?'c-warn':'c-ok'}">${k.bad?'!':k.w?'?':'✓'}</span><span>${k.t}</span></li>`).join('')}</ul>
   <div class="form">
    <label>Data de execução<input id="g-data" type="date" value="${d.data||todayISO()}"></label>
    <label>Custo real/orçado R$<input id="g-custo" class="n" type="number" step="0.01" min="0" value="${d.custo!=null&&d.custo!==''?d.custo:(g.est??'')}" placeholder="informe"></label>
    ${g.alc?`<label>Aprovado por (${esc(regua.params.aprovador||'alçada')})<input id="g-alc" value="${esc(d.alc||'')}" placeholder="nome do aprovador"></label>`:''}
   </div>
   <label class="note" style="display:grid;gap:4px">Justificativa ${(!g.noPrazo||g.alc)?'<b>(obrigatória)</b>':'(opcional)'}<textarea id="g-just">${esc(d.just||'')}</textarea></label>
   <div class="row"><button class="btn pri" id="g-ok">Registrar etapa concluída</button><button class="btn" id="g-na">Marcar N.A. e liberar a próxima</button></div>
   <p class="note" id="g-err" style="margin:0;color:var(--bad)"></p>
   ${encerrarHTML(c)}
  </div>`;
}
function encerrarHTML(c){return `<details><summary class="note" style="cursor:pointer">Encerrar o caso (acordo, quitação ou baixa)</summary><div class="form" style="margin-top:10px">
  <label>Motivo<select id="e-mot"><option>Acordo / confissão de dívida</option><option>Quitado</option><option>Baixa para perda (PDD)</option></select></label>
  <label>Valor recuperado/acordado R$<input id="e-val" class="n" type="number" step="0.01" min="0" value="0"></label>
  <label>Data<input id="e-data" type="date" value="${todayISO()}"></label></div>
  <label class="note" style="display:grid;gap:4px;margin-top:8px">Justificativa<textarea id="e-just"></textarea></label><div style="margin-top:8px"><button class="btn" id="e-go">Encerrar caso</button></div></details>`}

async function salvarCaso(c){
  if(!db){toast('Base indisponível nesta visualização');return false}
  try{const body=JSON.parse(JSON.stringify(c));delete body.id;body.atualizado=new Date().toISOString();await db.collection('casos').doc(c.id).set(body);return true}
  catch(e){toast(e.code==='invalid_argument'?'Sem permissão para gravar nesta base':'Não foi possível salvar: '+(e.message||e.code));return false}
}
function bindCaso(c,g){
  const d=drafts[c.id];const on=(id,ev,fn)=>{const el=$(id);if(el)el[ev]=fn};
  on('#g-data','oninput',e=>d.data=e.target.value);
  on('#g-custo','oninput',e=>{d.custo=e.target.value;clearTimeout(d._t);d._t=setTimeout(()=>{const pos=e.target.selectionStart;renderCaso();const n=$('#g-custo');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(_){}}},500)});
  on('#g-alc','oninput',e=>d.alc=e.target.value);
  on('#g-just','oninput',e=>d.just=e.target.value);
  const registrar=async status=>{
    const gg=gate(c,d.custo);const err=$('#g-err');const just=(d.just||'').trim();
    if(status==='ok'){
      if(!gg.defOk){err.textContent='Informe o custo real ou orçado da etapa.';return}
      if(!gg.noPrazo&&!just){err.textContent='A etapa está sendo antecipada: escreva a justificativa.';return}
      if(gg.alc&&(!(d.alc||'').trim()||!just)){err.textContent='Acima do limite de custo: informe o aprovador e a justificativa.';return}
    } else if(!just){err.textContent='Para marcar N.A., escreva por que a etapa não se aplica.';return}
    const nc=JSON.parse(JSON.stringify(c));nc.etapas=nc.etapas||{};
    const custo=status==='ok'?Number(gg.custo)||0:0;const acum=gg.st.custoReal+custo;
    nc.etapas[gg.e.id]={status,data:d.data||todayISO(),dividaMomento:gg.div,custoEstimado:gg.est,custoReal:custo,custoAcum:acum,razao:gg.div?acum/gg.div:null,limite:gg.lim,antecipada:!gg.noPrazo,alcada:status==='ok'&&gg.alc?(d.alc||'').trim():'',just,decididoEm:new Date().toISOString()};
    if(await salvarCaso(nc)){drafts[c.id]={};toast(status==='ok'?'Etapa registrada':'Etapa marcada N.A.')}
  };
  on('#g-ok','onclick',()=>registrar('ok'));on('#g-na','onclick',()=>registrar('na'));
  on('#c-savediv','onclick',async()=>{const nc={...c,divida:Number($('#c-div').value)||0,pdd:Number($('#c-pdd').value)||0};if(await salvarCaso(nc))toast('Valores atualizados')});
  on('#c-saveobs','onclick',async()=>{if(await salvarCaso({...c,obs:$('#c-obs').value}))toast('Observação salva')});
  on('#c-undo','onclick',async()=>{const et=etapasAtivas();const last=[...et].reverse().find(e=>(c.etapas||{})[e.id]);if(!last)return;const nc=JSON.parse(JSON.stringify(c));delete nc.etapas[last.id];if(await salvarCaso(nc))toast('Etapa desfeita')});
  on('#c-reopen','onclick',async()=>{const nc={...c};delete nc.encerrado;if(await salvarCaso(nc))toast('Caso reaberto')});
  on('#e-go','onclick',async()=>{const nc={...c,encerrado:{motivo:$('#e-mot').value,valor:Number($('#e-val').value)||0,data:$('#e-data').value||todayISO(),just:$('#e-just').value.trim()}};if(await salvarCaso(nc))toast('Caso encerrado')});
  on('#c-del','onclick',()=>{confirmDel={id:c.id,step:1};drawConfirm(c)});
}
function drawConfirm(c){
  const box=$('#c-confirm');if(!confirmDel||confirmDel.id!==c.id){box.innerHTML='';return}
  box.innerHTML=`<div class="confirm">${confirmDel.step===1?'Excluir o caso e todo o histórico de decisões?':'Confirme de novo: a exclusão não pode ser desfeita.'}<button class="btn sm danger" id="cd-yes">${confirmDel.step===1?'Sim, excluir':'Excluir definitivamente'}</button><button class="btn sm" id="cd-no">Cancelar</button></div>`;
  $('#cd-no').onclick=()=>{confirmDel=null;drawConfirm(c)};
  $('#cd-yes').onclick=async()=>{if(confirmDel.step===1){confirmDel.step=2;drawConfirm(c);return}
    try{await db.collection('casos').doc(c.id).delete();selId=null;confirmDel=null;toast('Caso excluído')}catch(e){toast('Não foi possível excluir')}};
}

// ---------- novo caso ----------
$('#b-novo').onclick=()=>{$('#novo').hidden=!$('#novo').hidden};
$('#n-cancel').onclick=()=>{$('#novo').hidden=true};
$('#novo').addEventListener('submit',async ev=>{ev.preventDefault();
  if(!db){toast('Base indisponível');return}
  const c={luc:$('#n-luc').value.trim(),loja:$('#n-loja').value.trim().toUpperCase(),shopping:$('#n-shop').value.trim(),situacao:$('#n-sit').value,divida:Number($('#n-div').value)||0,pdd:Number($('#n-pdd').value)||0,vencimento:$('#n-venc').value,garantia:$('#n-gar').value,obs:$('#n-obs').value.trim(),etapas:{},criado:new Date().toISOString()};
  try{const ref=await db.collection('casos').add(c);selId=ref.id;$('#novo').reset();$('#novo').hidden=true;toast('Caso aberto na etapa 1')}catch(e){toast(e.code==='quota_exceeded'?'Base cheia: exclua casos encerrados antigos':'Não foi possível salvar')}
});
['#f-shop','#f-st'].forEach(s=>$(s).onchange=()=>renderLista());

// ---------- régua ----------
function renderRegua(){
  if(!editRegua&&regua)editRegua=JSON.parse(JSON.stringify(regua));
  $('#r-vazia').hidden=!!editRegua;$('#r-perm').hidden=canEditRegua;
  const R=editRegua||{etapas:[],params:{}};
  $('#r-body').innerHTML=R.etapas.map((e,i)=>`<tr data-i="${i}">
   <td class="num">${i+1}<div class="row" style="gap:2px;flex-wrap:nowrap"><button class="btn sm" data-mv="-1" aria-label="Subir" ${i===0?'disabled':''}>↑</button><button class="btn sm" data-mv="1" aria-label="Descer" ${i===R.etapas.length-1?'disabled':''}>↓</button></div></td>
   <td><input data-f="nome" value="${esc(e.nome)}" aria-label="Nome da etapa"></td>
   <td><select data-f="resp">${['Shopping','Jurídico','Terceiro'].map(o=>`<option ${o===e.resp?'selected':''}>${o}</option>`).join('')}</select></td>
   <td><input class="n" style="width:70px" data-f="gatilho" type="number" value="${e.gatilho}"></td>
   <td><input class="n" style="width:70px" data-f="intervalo" type="number" value="${e.intervalo}"></td>
   <td><input class="n" data-f="fixo" type="number" step="0.01" value="${e.fixo}"></td>
   <td><input class="n" style="width:70px" data-f="pct" type="number" step="0.1" value="${e.pct}"></td>
   <td style="text-align:center"><input data-f="definido" type="checkbox" ${e.definido?'checked':''} aria-label="Custo definido" style="width:auto"></td>
   <td><input class="n" data-f="minDiv" type="number" step="100" value="${e.minDiv}"></td>
   <td><select data-f="aplica">${[['todas','Todas'],['ativa','Só ativa'],['inativa','Só inativa']].map(([v,l])=>`<option value="${v}" ${v===e.aplica?'selected':''}>${l}</option>`).join('')}</select></td>
   <td><button class="btn sm danger" data-rm aria-label="Remover etapa">×</button></td></tr>`).join('');
  $('#p-lim').value=R.params.limite??10;$('#p-att').value=R.params.atencao??70;$('#p-apr').value=R.params.aprovador??'';
  document.querySelectorAll('#r-body tr').forEach(tr=>{const i=+tr.dataset.i;
    tr.querySelectorAll('[data-f]').forEach(inp=>inp.onchange=()=>{const f=inp.dataset.f;const v=inp.type==='checkbox'?inp.checked:inp.type==='number'?Number(inp.value)||0:inp.value;editRegua.etapas[i][f]=v});
