.rolagem { overflow-x: auto; }
.obs-op { font-size: 12.5px; color: var(--ink-2); background: var(--atencao-soft); border-left: 3px solid var(--atencao); padding: 6px 9px; border-radius: 0 4px 4px 0; margin: 0; }
