.opcoes summary { cursor: pointer; color: var(--accent); }
.opcoes details p { margin: 6px 0; }

/* ------------------------------------------------------------------- tiles */
.resumo {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(178px, 1fr));
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r); overflow: hidden; margin-bottom: 22px;
}
.tile { padding: 14px 16px 15px; display: flex; flex-direction: column; gap: 3px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
