.tile .apoio { font-size: 13.5px; color: var(--ink-3); }

/* ----------------------------------------------------------------- controles */
.controles {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r);
  padding: 12px 16px; margin-bottom: 22px;
}
.campo { display: flex; align-items: center; gap: 9px; }
.campo label { font-size: 13.5px; font-weight: 600; color: var(--ink-2); }
input[type="range"] { width: 130px; accent-color: var(--accent); }
select, button.acao, input.entrada {
  font-family: var(--sans); font-size: 14.5px; color: var(--ink);
  background: var(--surface-2); border: 1px solid var(--line-strong);
  border-radius: 4px; padding: 5px 9px;
}
select, button.acao { cursor: pointer; }
button.acao:hover, select:hover { border-color: var(--accent); }
