.leitura-yield { font-family: var(--mono); font-size: 16px; font-weight: 600; min-width: 46px; }
.espaco { flex: 1; }

/* -------------------------------------------------------------------- seção */
section { margin-bottom: 34px; }
.cabecalho-secao {
  display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 12px;
}
.cabecalho-secao h2 { font-family: var(--serif); font-size: 25px; font-weight: 600; margin: 0; letter-spacing: -.01em; }
.cabecalho-secao .nota { font-size: 14px; color: var(--ink-3); max-width: 62ch; }

/* ------------------------------------------------------------------- linhas */
.pilha { display: flex; flex-direction: column; gap: 8px; }
.linha {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r);
  border-left: 4px solid var(--faixa, var(--neutro)); box-shadow: var(--sombra); overflow: hidden;
}
.linha[data-farol="compra-forte"], .linha[data-farol="compra"] { --faixa: var(--bom); }
.linha[data-farol="manter"]  { --faixa: var(--atencao); }
.linha[data-farol="reduzir"] { --faixa: var(--ruim); }
.linha[data-farol="fora"]    { --faixa: var(--neutro); }

.linha > summary {
  display: grid; align-items: center; gap: 10px 14px; padding: 12px 14px; cursor: pointer; list-style: none;
  grid-template-columns: minmax(130px, 1.2fr) minmax(112px, 1fr) repeat(3, minmax(80px, .85fr)) minmax(118px, 1fr) minmax(118px, .9fr) minmax(190px, 1.5fr) 30px;
}
.linha > summary::-webkit-details-marker { display: none; }
.linha > summary:hover { background: var(--surface-2); }
@media (max-width: 1180px) {
  .linha > summary { grid-template-columns: minmax(120px, 1.1fr) minmax(104px, 1fr) repeat(2, minmax(80px, 1fr)) minmax(118px, 1fr) minmax(180px, 1.4fr) 28px; }
  .celula[data-opcional] { display: none; }
}
@media (max-width: 760px) {
  .linha > summary { grid-template-columns: 1fr 1fr; gap: 10px 12px; }
  .celula[data-opcional] { display: flex; }
  .celula.larga { grid-column: 1 / -1; }
  .chevron { display: none; }
}

.identidade { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.identidade .tk { font-family: var(--mono); font-size: 18px; font-weight: 600; letter-spacing: -.01em; }
.identidade .nm { font-size: 13px; color: var(--ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.identidade .editada { font-size: 12px; color: var(--accent); font-weight: 600; }
.celula { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.celula .dado { font-family: var(--mono); font-size: 15px; font-variant-numeric: tabular-nums; }
.celula .dado.grande { font-size: 17px; font-weight: 500; }
