.celula.cotacao .var { display: inline-flex; align-items: center; gap: 4px; align-self: flex-start; font-size: 12.5px; font-weight: 700; padding: 1px 7px; border-radius: 999px; font-variant-numeric: tabular-nums; }
.celula.cotacao .var.pos { background: var(--bom-soft); color: var(--bom); }
.celula.cotacao .var.neg { background: var(--ruim-soft); color: var(--ruim); }
.celula.cotacao .var.zero { background: var(--neutro-soft); color: var(--ink-2); }
.celula.cotacao .fonte { font-size: 11px; color: var(--ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* farol */
.farol {
  display: inline-flex; align-items: center; gap: 7px; align-self: flex-start;
  padding: 4px 9px 4px 7px; border-radius: 999px;
  font-size: 13px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase;
  border: 1px solid transparent; white-space: nowrap;
}
.farol .luz { width: 8px; height: 8px; border-radius: 50%; background: currentColor; flex: none; }
.farol[data-f="compra-forte"] { color: var(--bom); background: var(--bom-soft); border-color: var(--bom); }
.farol[data-f="compra"]       { color: var(--bom); background: transparent; border-color: var(--bom); }
.farol[data-f="manter"]       { color: var(--atencao); background: var(--atencao-soft); border-color: var(--atencao); }
.farol[data-f="reduzir"]      { color: var(--ruim); background: var(--ruim-soft); border-color: var(--ruim); }
.farol[data-f="fora"]         { color: var(--neutro); background: var(--neutro-soft); border-color: var(--line-strong); }

/* barra divergente */
.medidor { display: flex; flex-direction: column; gap: 3px; }
.trilho { position: relative; height: 9px; background: var(--surface-3); border-radius: 2px; overflow: hidden; }
.trilho::after { content: ""; position: absolute; left: 50%; top: -2px; bottom: -2px; width: 1px; background: var(--line-strong); }
.trilho .barra { position: absolute; top: 0; bottom: 0; border-radius: 2px; }
.trilho .barra[data-lado="abaixo"] { background: var(--bom); }
.trilho .barra[data-lado="acima"] { background: var(--ruim); }
.medidor .legenda { font-family: var(--mono); font-size: 12.5px; color: var(--ink-3); white-space: nowrap; }

/* leitura gráfica + recomendação */
.grafico { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.grafico-topo { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.grafico-link {
  display: inline-flex; align-items: center; gap: 6px; font-size: 13.5px; font-weight: 600; text-decoration: none;
  color: var(--accent); background: var(--accent-soft); border: 1px solid transparent; border-radius: 4px;
  padding: 4px 9px; white-space: nowrap;
}
.grafico-link:hover { border-color: var(--accent); }
.niveis { font-family: var(--mono); font-size: 12.5px; color: var(--ink-3); white-space: nowrap; }
.reco {
  display: inline-flex; align-items: flex-start; gap: 6px; font-size: 13.5px; font-weight: 600; line-height: 1.3;
  color: var(--ink); padding: 3px 0;
}
.reco::before { content: ""; width: 3px; align-self: stretch; border-radius: 2px; background: var(--reco-cor, var(--neutro)); flex: none; }
.reco[data-tom="bom"] { --reco-cor: var(--bom); }
.reco[data-tom="atencao"] { --reco-cor: var(--atencao); }
.reco[data-tom="ruim"] { --reco-cor: var(--ruim); }
.reco[data-tom="neutro"] { --reco-cor: var(--neutro); color: var(--ink-2); font-weight: 500; }
.chevron { color: var(--ink-3); transition: transform .18s ease; justify-self: end; }
.linha[open] .chevron { transform: rotate(90deg); }
@media (prefers-reduced-motion: reduce) { .chevron { transition: none; } }

/* -------------------------------------------------------------- detalhe */
.detalhe {
  border-top: 1px solid var(--line); background: var(--surface-2); padding: 18px 16px 20px;
  display: grid; gap: 20px; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
}
.detalhe .inteira { grid-column: 1 / -1; }
@media (max-width: 860px) { .detalhe { grid-template-columns: 1fr; } }
.detalhe h4 {
  font-family: var(--sans); font-size: 12.5px; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--ink-3); margin: 0 0 8px;
}
.bloco + .bloco { margin-top: 18px; }
.resultado-txt { margin: 0; font-size: 16px; color: var(--ink-2); max-width: 68ch; }
.indicadores {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(158px, 1fr));
  background: var(--surface); border: 1px solid var(--line); border-radius: 4px; overflow: hidden;
}
.indicadores div { padding: 8px 10px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.indicadores dt { font-size: 12.5px; color: var(--ink-3); }
.indicadores dd { margin: 1px 0 0; font-family: var(--mono); font-size: 14.5px; font-weight: 500; }
.indicadores dd small { display: block; font-family: var(--sans); font-size: 12.5px; font-weight: 400; color: var(--ink-3); }
ul.lista { margin: 0; padding-left: 17px; font-size: 15px; color: var(--ink-2); }
ul.lista li { margin-bottom: 5px; }
ul.lista li::marker { color: var(--ink-3); }
ul.noticias { list-style: none; margin: 0; padding: 0; font-size: 15px; }
ul.noticias li { padding: 6px 0; border-bottom: 1px dotted var(--line-strong); }
ul.noticias li:last-child { border-bottom: 0; }
ul.noticias .data { font-family: var(--mono); font-size: 12.5px; color: var(--ink-3); display: block; }

.memoria { border: 1px solid var(--line-strong); border-radius: 4px; background: var(--surface); padding: 11px 13px; font-size: 14.5px; color: var(--ink-2); }
.memoria p { margin: 0 0 8px; }
.memoria p:last-child { margin-bottom: 0; }
.memoria .conta { font-family: var(--mono); font-size: 14.5px; color: var(--ink); margin-bottom: 6px; }
.confianca { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; }
.pontos { display: inline-flex; gap: 2px; }
.pontos i { width: 6px; height: 6px; border-radius: 50%; background: var(--line-strong); display: block; }
.pontos i.on { background: var(--marcador, var(--ink-2)); }
.confianca[data-nivel="alta"] { color: var(--bom); --marcador: var(--bom); }
.confianca[data-nivel="media"] { color: var(--atencao); --marcador: var(--atencao); }
.confianca[data-nivel="baixa"] { color: var(--ruim); --marcador: var(--ruim); }

/* ajuste de posição */
.ajuste {
  background: var(--surface); border: 1px solid var(--line-strong); border-radius: 4px; padding: 12px 14px;
  display: grid; gap: 14px; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
}
@media (max-width: 860px) { .ajuste { grid-template-columns: 1fr; } }
.ajuste h5 { margin: 0 0 8px; font-size: 12.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-3); font-weight: 700; }
.formulario { display: flex; flex-wrap: wrap; gap: 8px 10px; align-items: flex-end; }
.formulario label { display: flex; flex-direction: column; gap: 3px; font-size: 12.5px; color: var(--ink-3); font-weight: 600; }
.formulario .previa { font-family: var(--mono); font-size: 13.5px; color: var(--ink-2); width: 100%; margin-top: 2px; }
.operacoes { list-style: none; margin: 8px 0 0; padding: 0; font-size: 14px; }
.operacoes li { display: flex; gap: 10px; align-items: center; padding: 5px 0; border-bottom: 1px dotted var(--line-strong); }
