function mescla(snap, atual, prefixo) {
  const novo = {};
  snap.docs.forEach(d => { novo[d.id] = {...d.data()}; });
  Object.keys(pend).forEach(k => {
    if (pend[k] > 0 && k.startsWith(prefixo)) { const id = k.slice(prefixo.length); if (atual[id]) novo[id] = atual[id]; else delete novo[id]; }
  });
  return novo;
}
async function iniciar() {
  atualizar();
  let store = null;
  try { store = window.claude && window.claude.use ? await window.claude.use("db") : null; } catch (e) { store = null; }
