  const role = () => localStorage.getItem('role') || 'admin';
  const load = () => JSON.parse(localStorage.getItem('mockdb') || '{"etapas":{},"datas":{}}');
  const subs = {etapas: [], datas: []};
  const fire = col => { const m = load()[col]; const snap = {docs: Object.entries(m).map(([id, d]) => ({id, data: () => d}))}; subs[col].forEach(f => f(snap)); };
  const mayWrite = col => role() === 'admin' || (role() === 'interact' && col === 'datas');
  const db = {
    doc: path => { const [col, id] = path.split('/'); return {
      set: async data => { if (!mayWrite(col)) throw {code: 'invalid_argument'}; const m = load(); m[col][id] = data; localStorage.setItem('mockdb', JSON.stringify(m)); setTimeout(() => fire(col), 20); },
      delete: async () => { if (!mayWrite(col)) throw {code: 'invalid_argument'}; const m = load(); delete m[col][id]; localStorage.setItem('mockdb', JSON.stringify(m)); setTimeout(() => fire(col), 20); } }; },
