"""Extensão do valuation.py para empresas com owner earnings hoje NEGATIVOS.
Mesma lógica (cenários, ponderado, TIR, entrada/saída por nota), mas com fluxos explícitos
ano a ano + perpetuidade, e caixa líquido somado ao valor."""
import json
MARGENS={"A":0.225,"B":0.325,"C":0.45}
def vp(flows,gt,r,caixa,acoes):
    pv=sum(f/(1+r)**(t+1) for t,f in enumerate(flows))
    tv=flows[-1]*(1+gt)/(r-gt)/(1+r)**len(flows)
    return (pv+tv+caixa)/acoes
def pond(c,r): return sum(s["prob"]*vp(s["flows"],s["gt"],r,c["caixa"],c["acoes"]) for s in c["cen"].values())
def bis(f,lo,hi):
    for _ in range(200):
        m=(lo+hi)/2
        if (f(m)>0)==(f(lo)>0): lo=m
        else: hi=m
    return (lo+hi)/2
def run(c):
    r=c["taxa"];p=c["preco"];n=c["nota"]
    out={"valores":{k:vp(s["flows"],s["gt"],r,c["caixa"],c["acoes"]) for k,s in c["cen"].items()}}
    b=pond(c,r); out["pond"]=b
    out["tir"]=bis(lambda x:pond(c,x)-p,max(s["gt"] for s in c["cen"].values())+0.002,1.0)
    m=MARGENS[n]; out["entrada"]=b*(1-m); out["margem"]=m
    out["saida"]= b if n=="C" else b*1.15
    # reverso: fator multiplicador sobre fluxos positivos do cenário base que justifica o preço
    base=c["cen"]["base"]
    def f(k):
        fl=[x*k if x>0 else x for x in base["flows"]]
        return vp(fl,base["gt"],r,c["caixa"],c["acoes"])-p
    out["fator_rev"]=bis(f,0.1,20)
    sens={}
    for dr in (-0.01,0,0.01):
        for dg in (-0.01,0,0.01):
            c2=json.loads(json.dumps(c))
            for s in c2["cen"].values(): s["gt"]+=dg
            sens[(dr,dg)]=pond(c2,r+dr)
    out["sens"]=sens
    return out
def path(start,years_growth,margins,rev0):
    rev=rev0; fl=[]
    for g,m in zip(years_growth,margins):
        rev*=1+g; fl.append(rev*m)
    return fl,rev
if __name__=="__main__":
    # ---------- MP (US$ mi) 2027..2036 -------------
    mp={"empresa":"MP","preco":49.30,"acoes":202.6,"caixa":471+336,"taxa":0.12,"nota":"C","cen":{
     "bear":{"prob":0.25,"gt":0.02,"flows":[-350,-350,-100,50,150,250,258,265,273,281]},
     "base":{"prob":0.50,"gt":0.03,"flows":[-300,-250,0,250,400,424,449,476,505,535]},
     "bull":{"prob":0.25,"gt":0.03,"flows":[-250,-100,200,500,750,810,875,945,1020,1100]}}}
    # ---------- OUST: receita 2026E 221; OE = receita x margem OE (após SBC, capex, impostos)
    def oust(gs,ms): return path(0,gs,ms,221)[0]
    ou={"empresa":"OUST","preco":41.37,"acoes":72.1,"caixa":245,"taxa":0.13,"nota":"C","cen":{
     "bear":{"prob":0.25,"gt":0.02,"flows":oust([.15]*5+[.06]*5,[-.30,-.20,-.10,0,.03,.05,.05,.05,.05,.05])},
     "base":{"prob":0.50,"gt":0.03,"flows":oust([.30]*5+[.12]*5,[-.25,-.12,0,.07,.12,.14,.15,.16,.16,.16])},
     "bull":{"prob":0.25,"gt":0.03,"flows":oust([.45]*5+[.15]*5,[-.20,-.05,.08,.15,.18,.20,.20,.20,.20,.20])}}}
    for c in (mp,ou):
        o=run(c); print(c["empresa"],{k:round(v,1) for k,v in o["valores"].items()},"pond",round(o["pond"],1),
          "TIR",round(o["tir"]*100,1),"entrada",round(o["entrada"],1),"saida",round(o["saida"],1),"fator_rev",round(o["fator_rev"],2))
        print("  sens",{k:round(v,1) for k,v in o["sens"].items()})
    json.dump({"mp":mp,"ou":ou},open("cfg_explicito.json","w"))
EOF
