    s.addShape(pres.shapes.ARC, {
      x: x + i * 0.45, y: y + i * 0.45, w: d, h: d,
      angleRange: [200 + i * 25, 20 + i * 25],
      line: { color, width: 1.25 }, fill: { type: "none" },
    });
  }
}
function title(s, t, sub) {
