  s.addNotes("Deck de apresentação da revisão do Book (v1.1 → v2.0) com base no PES 2020 e nos objetivos atualizados do projeto. Tudo que é proposta está sinalizado como tal.");
}

// 2 OBJETIVO + NÚMEROS
{
